# ---------------------------------------------------
#  SUPABASE
# ---------------------------------------------------

def get_supabase() -> Client:
    """Cliente Supabase isolado por sessão (guardado em st.session_state),
    e não mais em @st.cache_resource. O @st.cache_resource criava UM único
    client compartilhado por todo o processo do servidor — como o login
    (supabase.auth.sign_in_with_password) guarda o token de sessão dentro
    do próprio client, isso fazia o token de um usuário "vazar" pra dentro
    das chamadas de outro usuário rodando ao mesmo tempo no mesmo processo.
    Na prática, isso podia fazer o RLS barrar silenciosamente operações
    que deveriam funcionar pro usuário atual (ex.: excluir notificação
    devolvia sucesso mas não apagava nada, porque o delete rodava com o
    token de outra sessão). Guardando o client em st.session_state, cada
    aba/usuário tem o seu próprio client — e ele persiste entre os reruns
    da mesma sessão, então o login continua funcionando normalmente.

    Timeout do AUTH (login/cadastro) configurado à mão: por padrão, o
    `supabase-py` só define um timeout generoso (120s) pro client de
    BANCO (`postgrest`, via `ClientOptions.postgrest_client_timeout`).
    O client de AUTH (`gotrue`, usado em `sign_in_with_password` /
    `sign_up`) não usa essa opção — se nenhum `httpx_client` for passado
    em `ClientOptions`, ele cria um `httpx.Client()` totalmente padrão
    por baixo dos panos, e o timeout padrão do `httpx` pra QUALQUER
    operação (conexão, leitura, escrita) é de só 5 segundos. Isso batia
    direto num caso real: um pico de IOwait no Postgres do Supabase
    (a query de auth precisa ler `auth.users`) fazia a resposta demorar
    mais que 5s, e o `httpx` desistia com "The read operation timed
    out" — mesmo o banco estando saudável o bastante pra responder
    logo em seguida, só mais devagar que o normal. Passar um
    `httpx_client` próprio com timeout maior (30s de leitura, 10s só
    pra abrir a conexão) resolve isso sem mudar nada do lado do
    Supabase."""
    if "_supabase_client" not in st.session_state:
        url = st.secrets["SUPABASE_URL"]
        key = st.secrets["SUPABASE_KEY"]
        # Importante: `ClientOptions` tem que vir do topo do pacote
        # (`from supabase import ClientOptions`), não de
        # `supabase.lib.client_options` — esse último é a dataclass
        # BASE, que não tem o campo `httpx_client` (só existe nas
        # subclasses `SyncClientOptions`/`AsyncClientOptions`; o
        # `supabase/__init__.py` já expõe `SyncClientOptions` com o
        # apelido `ClientOptions`). Importar do lugar errado dá
        # `TypeError: unexpected keyword argument 'httpx_client'`
        # direto na inicialização do app.
        from supabase import ClientOptions
        _opcoes_supabase = ClientOptions(
            httpx_client=httpx.Client(
                # V87: coletas grandes de Google Ads podem atualizar um JSONB
                # considerável. 30s ainda gerava "The read operation timed out"
                # em instabilidades passageiras do gateway do Supabase.
                timeout=httpx.Timeout(90.0, connect=15.0)
            ),
        )
        st.session_state["_supabase_client"] = create_client(url, key, options=_opcoes_supabase)
    return st.session_state["_supabase_client"]


supabase = get_supabase()

# ---------------------------------------------------
# V98 — CAMADA RESILIENTE DE SUPABASE
# ---------------------------------------------------
# Centraliza retry/backoff para operações críticas. Antes, cada área tinha
# sua própria sequência de tentativas, com tempos e critérios diferentes.
_SUPABASE_ERROS_TRANSITORIOS = (
    "timeout", "timed out", "read operation", "connection reset",
    "connection lost", "server disconnected", "521", "502", "503", "504",
    "57p03", "database system is not accepting connections", "upstream",
)

def _erro_supabase_transitorio(exc) -> bool:
    s = str(exc).lower()
    return any(tok in s for tok in _SUPABASE_ERROS_TRANSITORIOS)

def _supabase_resiliente(fn, *, operacao: str = "supabase", tentativas: int = 4,
                         backoff=(1, 2, 4, 8), somente_transitorios: bool = True):
    """Executa `fn()` com retry/backoff consistente.
    Erros de regra/dado não ficam sendo repetidos à toa; instabilidade de
    rede/gateway recebe novas tentativas automáticas."""
    ultimo = None
    for i in range(max(1, tentativas)):
        try:
            with _recurso_api_io():
                return fn()
        except Exception as exc:
            ultimo = exc
            if somente_transitorios and not _erro_supabase_transitorio(exc):
                raise
            if i >= tentativas - 1:
                break
            espera = backoff[min(i, len(backoff) - 1)] if backoff else 1
            print(f"[SUPABASE] retry {i+1}/{tentativas-1} operacao={operacao!r} "
                  f"em {espera}s: {exc!r}", flush=True)
            time.sleep(espera)
    raise ultimo

def _persistir_cache_ads_db(user_id: str, coluna: str, payload: dict,
                            tentativas: int = 5):
    """Persistência comum a Meta Ads e Google Ads."""
    return _supabase_resiliente(
        lambda: supabase.table("ci_dados").update({coluna: payload})
                .eq("user_id", user_id).execute(),
        operacao=f"salvar_{coluna}",
        tentativas=tentativas,
        backoff=(2, 4, 8, 12, 20),
    )

# ---------------------------------------------------
# COORDENADOR CENTRAL DE JOBS
# ---------------------------------------------------
# OCR e migração já tinham travas próprias; agora compartilham também uma
# visão única de "job lógico ativo" para impedir workers duplicados entre
# subsistemas diferentes.
_jobs_lock = threading.RLock()
_jobs_ativos = set()

def _job_key(tipo: str, user_id: str, escopo: str = ""):
    return (str(tipo), str(user_id), str(escopo or ""))

def _job_try_acquire(tipo: str, user_id: str, escopo: str = "") -> bool:
    chave = _job_key(tipo, user_id, escopo)
    with _jobs_lock:
        if chave in _jobs_ativos:
            return False
        _jobs_ativos.add(chave)
        return True

def _job_release(tipo: str, user_id: str, escopo: str = ""):
    with _jobs_lock:
        _jobs_ativos.discard(_job_key(tipo, user_id, escopo))

def _job_is_active(tipo: str, user_id: str, escopo: str = "") -> bool:
    with _jobs_lock:
        return _job_key(tipo, user_id, escopo) in _jobs_ativos

def _job_any_active(tipo: str, user_id: str) -> bool:
    _tipo = str(tipo)
    _uid = str(user_id)
    with _jobs_lock:
        return any(k[0] == _tipo and k[1] == _uid for k in _jobs_ativos)

def _job_run_guarded(tipo: str, user_id: str, escopo: str, target, args=(), kwargs=None):
    """Executa um job e sempre libera sua chave lógica ao terminar."""
    try:
        return target(*(args or ()), **(kwargs or {}))
    finally:
        _job_release(tipo, user_id, escopo)

def _job_start_thread(tipo: str, user_id: str, escopo: str, target, *,
                      args=(), kwargs=None, daemon=True, name=None) -> bool:
    """Abre uma única thread para o job. False = já havia job igual ativo."""
    if not _job_try_acquire(tipo, user_id, escopo):
        return False
    try:
        threading.Thread(
            target=_job_run_guarded,
            args=(tipo, user_id, escopo, target, args, kwargs),
            daemon=daemon,
            name=name,
        ).start()
        return True
    except Exception:
        _job_release(tipo, user_id, escopo)
        raise


# ---------------------------------------------------
#  CLOUDFLARE R2 (armazenamento permanente de mídias)
# ---------------------------------------------------
# R2 é compatível com a API S3, então usamos boto3 apontando pro
# endpoint da Cloudflare. Credenciais e nomes de bucket vêm dos
# secrets do Streamlit (ver instruções de configuração no final
# deste bloco / no README de deploy).

import boto3
from botocore.config import Config as _BotoConfig
import hashlib
import html
import mimetypes

R2_BUCKET      = st.secrets.get("R2_BUCKET_NAME", "")
R2_PUBLIC_BASE = st.secrets.get("R2_PUBLIC_BASE_URL", "").rstrip("/")

@st.cache_resource
def get_r2_client():
    """Cliente S3-compatível apontando pro Cloudflare R2.
    Retorna None se as credenciais não estiverem configuradas —
    nesse caso o pipeline de mídia cai de volta pro link original."""
    account_id = st.secrets.get("R2_ACCOUNT_ID", "")
    access_key = st.secrets.get("R2_ACCESS_KEY_ID", "")
    secret_key = st.secrets.get("R2_SECRET_ACCESS_KEY", "")
    if not (account_id and access_key and secret_key and R2_BUCKET and R2_PUBLIC_BASE):
        return None
    return boto3.client(
        "s3",
        endpoint_url=f"https://{account_id}.r2.cloudflarestorage.com",
        aws_access_key_id=access_key,
        aws_secret_access_key=secret_key,
        config=_BotoConfig(signature_version="s3v4"),
        region_name="auto",
    )

r2_client = get_r2_client()

# ---------------------------------------------------
#  WHISPER LOCAL (transcrição de áudio dos vídeos, sem custo de API)
# ---------------------------------------------------
# Usado pra transcrever o áudio dos vídeos de anúncios, assim as análises
# de IA recebem o texto falado no vídeo em vez do vídeo em si (a IA de
# análise, Gemini, não recebe mais o arquivo de vídeo — só a transcrição).
# Roda o modelo Whisper open-source localmente (via faster-whisper), na
# CPU do próprio servidor — sem chamar API paga nenhuma. O "custo" aqui é
# tempo de processamento, não dinheiro.

@st.cache_resource(show_spinner=False)
def get_whisper_model():
    """Carrega o modelo Whisper local uma única vez e mantém em cache
    pelo resto do processo. Modelo "base": bom equilíbrio entre
    qualidade e velocidade/RAM em CPU. Retorna None se o pacote
    faster-whisper não estiver instalado, se o download/carregamento
    travar (ver timeout abaixo) ou se falhar por qualquer outro motivo
    — nesse caso os vídeos seguem sem transcrição, sem quebrar o resto
    do app.

    IMPORTANTE: na primeira execução em cada novo container (todo
    redeploy no Streamlit Cloud é um container novo), o faster-whisper
    baixa os pesos do modelo lá do Hugging Face Hub. Sem HF_TOKEN
    configurado nos secrets, esse download é anônimo e pode ficar lento
    ou até travar (rate limit / rede instável) — e como isso rodava
    direto no import do módulo (fora de função, antes de qualquer UI
    do Streamlit), um download travado prendia o app inteiro na tela
    de carregamento pra sempre. Por isso o carregamento roda numa
    thread separada com timeout (mesmo padrão já usado em
    _transcrever_video_whisper pro transcribe()) e só é chamado sob
    demanda (lazy, ver whisper_model_ou_none() abaixo), nunca no
    import."""
    import concurrent.futures as _cf

    def _carregar():
        from faster_whisper import WhisperModel
        tamanho_modelo = st.secrets.get("WHISPER_MODEL_SIZE", "base")
        return WhisperModel(tamanho_modelo, device="cpu", compute_type="int8")

    _timeout_carregar = st.secrets.get("WHISPER_LOAD_TIMEOUT_SEGUNDOS", 90)
    try:
        with _cf.ThreadPoolExecutor(max_workers=1) as _exec:
            _future = _exec.submit(_carregar)
            try:
                return _future.result(timeout=_timeout_carregar)
            except _cf.TimeoutError:
                # Não dá pra matar a thread de download em andamento (ela
                # continua rodando sozinha em segundo plano, mesmo depois
                # do timeout — mesmo comportamento aceito no transcribe()).
                # O importante é o app não ficar preso esperando por ela.
                return None
    except Exception:
        return None


def whisper_model_ou_none():
    """Acesso lazy ao modelo Whisper: só dispara o carregamento (e o
    possível download do Hugging Face Hub) na primeira vez que alguém
    realmente precisa transcrever um vídeo — nunca no import do módulo.
    Assim, mesmo que o download trave ou demore, a UI do Streamlit sobe
    normalmente e o app fica utilizável; só a transcrição por Whisper
    fica indisponível nesse meio-tempo (fallback já tratado em quem
    chama isso, via checagens de `is None`)."""
    return get_whisper_model()


# ---------------------------------------------------
#  PLANOS — cota de ANÚNCIOS com mídia baixada/armazenada por mês
# ---------------------------------------------------
# Placeholder simples até o item 4 do roadmap (tabela uso_organizacao
# + billing de verdade) existir. O único ponto que precisa mudar
# quando o billing estiver pronto é obter_plano_usuario().
#
# IMPORTANTE: a cota é contada por ANÚNCIO (ad_id distinto), não por linha
# individual da tabela `midias`. Um mesmo anúncio pode ter várias imagens
# e/ou vídeo (cada upload bem-sucedido vira uma linha própria em `midias`
# — ver baixar_e_persistir_midia + persistir_midias_de_ads, que cria uma
# tarefa por URL de imagem/vídeo do anúncio, não uma por anúncio). Contar
# por linha inflava o consumo real: uma biblioteca com poucos anúncios mas
# 2-4 mídias cada batia o teto de 500 rapidinho sem ter nem perto de 500
# anúncios de verdade. Como isto é uma biblioteca de ANÚNCIOS, faz mais
# sentido cobrar por anúncio — ver _contar_midias_do_mes.
PLANOS_QUOTA_MIDIAS = {
    "free":    0,     # não baixa mídia — mantém o link original do Facebook (pode expirar)
    "starter": 50,    # até 50 ANÚNCIOS com mídia baixada/armazenada por mês
    "pro":     500,   # até 500 ANÚNCIOS com mídia baixada/armazenada por mês
    "agencia": None,  # ilimitado
}
# Revisado em jul/2026, depois da virada de métrica pra "por anúncio"
# (ver comentário acima): os números 500/50 foram mantidos de propósito,
# Starter (10x) e, na prática, representa um AUMENTO real de capacidade
# em ambos os planos (antes, 500/50 "mídias" cobriam bem menos anúncios
# de verdade do que 500/50 anúncios cobrem agora).

# Cota de concorrentes monitorados por plano — usada na aba "Uso do plano"
# do perfil, pra mostrar quanto da cota já foi usado. Precisa ficar em
# sincronia com o texto exibido nos cards de planos (aba "Plano").
PLANOS_QUOTA_CONCORRENTES = {
    "free":    1,
    "starter": 5,
    "pro":     20,
    "agencia": None,  # ilimitado
}

# Quantas vezes tentamos baixar a mesma mídia antes de desistir de vez.
# Sem esse teto, um link permanentemente quebrado (ex: anúncio removido
# no Facebook) ficaria sendo tentado pra sempre a cada coleta.
MAX_TENTATIVAS_MIDIA = 5

# Janela (em horas) usada pra marcar um link original da Meta como "vai
# expirar em breve" no card de Links Pendentes. URLs do CDN da Meta
# (scontent-*.fbcdn.net) trazem embutido um parâmetro "oe" — um timestamp
# Unix em hexadecimal com o instante exato em que aquele link para de
# funcionar. Isso permite saber a expiração real sem precisar de uma nova
# coleta. 48h é um valor de partida (link "na berlinda"); ajustável.
JANELA_EXPIRACAO_LINK_HORAS = 48

def _extrair_expiracao_url(url: str):
    """Extrai o timestamp de expiração embutido numa URL do CDN da Meta
    (parâmetro de query 'oe', hex = Unix timestamp em segundos). Devolve
    um datetime (UTC) ou None se a URL não tiver o parâmetro ou não for
    parseável — nesse caso o link entra como 'sem previsão', não como
    'não vai expirar'."""
    if not url:
        return None
    try:
        import urllib.parse as _urlparse
        import datetime as _dt_exp
        qs = _urlparse.urlparse(url).query
        oe = _urlparse.parse_qs(qs).get("oe", [None])[0]
        if not oe:
            return None
        return _dt_exp.datetime.fromtimestamp(int(oe, 16), _dt_exp.timezone.utc)
    except Exception:
        return None

def _classificar_links_expiracao(ads: list, horas: int = JANELA_EXPIRACAO_LINK_HORAS) -> dict:
    """Classifica os ANÚNCIOS (de uma lista de ads ainda com link
    original, ver encontrar_ads_com_link_original) pela urgência REAL de
    expiração, usando o timestamp exato embutido na URL da Meta (ver
    _extrair_expiracao_url) — nunca uma estimativa por data de coleta.

    Separa em dois grupos, porque são coisas diferentes pro usuário:
      - "expirados": o link já venceu (exp <= agora). Antes isso entrava
        junto com "expirando", como se fosse só "vai vencer logo" — mas
        um link já morto é um problema diferente (a mídia já pode estar
        quebrada agora) de um link que ainda funciona mas vai quebrar.
      - "expirando": ainda não venceu, mas vence dentro da janela.

    "agora" é recalculado a cada chamada em UTC, então o
    resultado reflete o instante real da renderização — cada rerun do
    Streamlit (refresh da página, navegação etc.) recalcula do zero
    contra o relógio atual, não guarda um valor "congelado" de uma
    coleta anterior.

    proxima_expiracao: o timestamp de expiração mais próximo entre os
    anúncios "expirando" (o mais urgente do grupo) — usado pra montar o
    texto "expira em Xh Ymin" com o tempo real restante, em vez do texto
    fixo "expira em até 48h" que não dizia se faltavam 47h ou 10 minutos.

    ids_expirados/ids_expirando: lista de {id, titulo, exp} de cada
    anúncio classificado em cada grupo — usada pra montar um tooltip
    (hover) nas badges do card, mostrando quais anúncios exatamente
    entraram na conta. Isso existe pra permitir conferir na prática se a
    classificação bate com a realidade (ex.: abrir o anúncio pelo id e
    ver se o link realmente está quebrado), em vez de confiar cegamente
    no número agregado."""
    import datetime as _dt_exp
    agora = _dt_exp.datetime.now(_dt_exp.timezone.utc)
    limite = agora + _dt_exp.timedelta(hours=horas)
    expirados = 0
    expirando = 0
    proxima_expiracao = None
    ids_expirados = []
    ids_expirando = []
    for ad in ads or []:
        _imagens_ad = ad.get("images") or []
        _videos_ad = ad.get("videos") or []
        # Mesma regra de encontrar_ads_com_link_original: se o anúncio tem
        # vídeo, só o link do vídeo importa (é dali que vem o thumb
        # exibido no card) — as imagens desse tipo de anúncio só aparecem
        # no modal opcional "🖼️ +N" e não derrubam nada visível se
        # expirarem, então não entram na conta de urgência.
        urls = _videos_ad if _videos_ad else _imagens_ad
        exp_mais_proxima = None
        for u in urls:
            if not u or (R2_PUBLIC_BASE and u.startswith(R2_PUBLIC_BASE)):
                continue
            exp = _extrair_expiracao_url(u)
            if exp and (exp_mais_proxima is None or exp < exp_mais_proxima):
                exp_mais_proxima = exp
        if exp_mais_proxima is None:
            continue
        _info_ad = {"id": ad.get("id", ""), "titulo": ad.get("titulo", ""), "exp": exp_mais_proxima}
        if exp_mais_proxima <= agora:
            expirados += 1
            ids_expirados.append(_info_ad)
        elif exp_mais_proxima <= limite:
            expirando += 1
            ids_expirando.append(_info_ad)
            if proxima_expiracao is None or exp_mais_proxima < proxima_expiracao:
                proxima_expiracao = exp_mais_proxima
    return {
        "expirados": expirados, "expirando": expirando, "proxima_expiracao": proxima_expiracao,
        "ids_expirados": ids_expirados, "ids_expirando": ids_expirando,
    }

def _montar_tooltip_ids(itens: list, agora=None) -> str:
    """Monta o texto do tooltip (atributo title=, tooltip nativo do
    navegador ao passar o mouse) listando os anúncios de uma badge de
    urgência — id, título (se houver) e a data/hora exata de expiração
    (UTC) daquele link, uma por linha. Limita a 20 itens pra não virar
    um tooltip gigante quando são centenas de anúncios; o restante só
    entra na contagem "+N outros"."""
    import datetime as _dt_tt
    agora = agora or _dt_tt.datetime.now(_dt_tt.timezone.utc)
    linhas = []
    for it in (itens or [])[:20]:
        _tit = f" — {it['titulo']}" if it.get("titulo") else ""
        _exp_str = it["exp"].strftime("%d/%m/%Y %H:%M UTC") if it.get("exp") else "?"
        linhas.append(f"id {it.get('id') or '?'}{_tit} (expira/expirou: {_exp_str})")
    if len(itens or []) > 20:
        linhas.append(f"+{len(itens) - 20} outros")
    return "\n".join(linhas)

def _formatar_tempo_restante(quando, agora=None) -> str:
    """Formata o tempo real restante até 'quando' (datetime UTC) de forma
    legível ('2d 4h', '3h 12min', '8min'), pra mostrar a contagem
    verdadeira em vez do texto fixo 'até 48h'. Recalculado a cada rerun
    do Streamlit, então sempre reflete o tempo restante no momento em
    que a página foi gerada (não "tica" sozinho na tela sem interação —
    pra isso seria preciso um componente JS com setInterval, que dá pra
    adicionar depois se for importante ter atualização contínua sem
    precisar recarregar/interagir com a página)."""
    import datetime as _dt_fmt
    agora = agora or _dt_fmt.datetime.now(_dt_fmt.timezone.utc)
    total_min = int((quando - agora).total_seconds() // 60)
    if total_min <= 0:
        return "menos de 1 min"
    dias, resto_min = divmod(total_min, 60 * 24)
    horas, minutos = divmod(resto_min, 60)
    if dias:
        return f"{dias}d {horas}h" if horas else f"{dias}d"
    if horas:
        return f"{horas}h {minutos}min" if minutos else f"{horas}h"
    return f"{minutos}min"

def obter_plano_usuario() -> str:
    # TODO: plugar no sistema real de assinatura/billing (item 4 do roadmap).
    # todo mundo na cota 0 do plano free antes do sistema de planos existir.
    # Trocar pra "free" (ou remover o default) assim que o billing entrar.
    return st.session_state.get("plano_usuario", "pro")

def _contar_midias_do_mes(user_id: str) -> int:
    """Conta quantos ANÚNCIOS distintos (ad_id) já tiveram pelo menos uma
    mídia baixada/persistida neste mês — é essa contagem que decide a cota
    do plano (ver PLANOS_QUOTA_MIDIAS e pode_baixar_midia). Conta por
    anúncio, não por linha da tabela `midias`: um mesmo anúncio pode gerar
    várias linhas (uma por imagem/vídeo), e contar por linha faria a cota
    estourar bem antes de a biblioteca ter perto de `limite` anúncios de
    verdade. Itens sem ad_id (não deveria acontecer no fluxo normal, mas
    por segurança) não entram na contagem."""
    try:
        import datetime as _dt
        inicio_mes = _dt.datetime.now().replace(
            day=1, hour=0, minute=0, second=0, microsecond=0
        ).isoformat()
        res = (
            supabase.table("midias")
            .select("ad_id")
            .eq("user_id", user_id)
            .gte("criado_em", inicio_mes)
            .not_.is_("ad_id", "null")
            .execute()
        )
        return len({row["ad_id"] for row in (res.data or []) if row.get("ad_id")})
    except Exception:
        return 0

def _contar_midias_do_mes_por_empresa(user_id: str) -> dict:
    """Quebra a mesma contagem de _contar_midias_do_mes (ANÚNCIOS distintos
    com mídia baixada/persistida neste mês) por empresa — usado na aba
    'Uso do plano' pra mostrar quanto da cota cada empresa monitorada
    (a própria empresa do usuário e cada concorrente) está consumindo.
    Devolve {nome_da_empresa: quantidade_de_anuncios}."""
    resultado = {}
    if not user_id:
        return resultado
    try:
        import datetime as _dt
        inicio_mes = _dt.datetime.now().replace(
            day=1, hour=0, minute=0, second=0, microsecond=0
        ).isoformat()
        res = (
            supabase.table("midias")
            .select("empresa, ad_id")
            .eq("user_id", user_id)
            .gte("criado_em", inicio_mes)
            .not_.is_("ad_id", "null")
            .execute()
        )
        _ids_por_empresa = {}
        for row in (res.data or []):
            aid = row.get("ad_id")
            emp = row.get("empresa") or ""
            if not aid or not emp:
                continue
            _ids_por_empresa.setdefault(emp, set()).add(aid)
        resultado = {emp: len(ids) for emp, ids in _ids_por_empresa.items()}
        return resultado
    except Exception:
        return resultado

def pode_baixar_midia(user_id: str) -> bool:
    limite = PLANOS_QUOTA_MIDIAS.get(obter_plano_usuario(), 0)
    if limite is None:
        return True
    if limite == 0:
        return False
    return _contar_midias_do_mes(user_id) < limite

def _slug_empresa(nome: str) -> str:
    nome = remover_acentos((nome or "").strip().lower())
    nome = re.sub(r"[^a-z0-9]+", "-", nome).strip("-")
    return nome or "sem-nome"

def _comprimir_imagem(conteudo: bytes, content_type: str):
    """Reduz o tamanho de imagens antes de subir pro R2: redimensiona se
    for muito larga e reencoda em WebP (ótima compressão, com suporte a
    transparência). Se algo der errado ou a Pillow não estiver disponível,
    devolve o conteúdo original sem comprimir — nunca quebra o upload."""
    try:
        from PIL import Image
        import io
        img = Image.open(io.BytesIO(conteudo))
        LARGURA_MAX = 1280
        if img.width > LARGURA_MAX:
            nova_altura = int(img.height * (LARGURA_MAX / img.width))
            img = img.resize((LARGURA_MAX, nova_altura), Image.LANCZOS)
        buffer = io.BytesIO()
        img.save(buffer, format="WEBP", quality=80, method=6)
        return buffer.getvalue(), "image/webp", ".webp"
    except Exception:
        return conteudo, content_type, None

def _comprimir_video(conteudo: bytes, content_type: str):
    """Reduz o tamanho de vídeos antes de subir pro R2: reencoda em H.264
    com CRF mais agressivo e limita a altura a 720p, usando o ffmpeg via
    subprocess (precisa estar instalado no sistema — ver packages.txt).
    Se algo der errado ou o ffmpeg não estiver disponível, devolve o
    conteúdo original sem comprimir — nunca quebra o upload."""
    import subprocess
    import tempfile
    import os
    import shutil

    if shutil.which("ffmpeg") is None:
        return conteudo, content_type, None

    ALTURA_MAX = 720

    try:
        with tempfile.TemporaryDirectory() as tmp:
            entrada = os.path.join(tmp, "entrada")
            saida = os.path.join(tmp, "saida.mp4")
            with open(entrada, "wb") as f:
                f.write(conteudo)

            cmd = [
                "ffmpeg", "-y",
                "-i", entrada,
                "-vf", f"scale=-2:'min({ALTURA_MAX},ih)'",
                "-c:v", "libx264", "-crf", "28", "-preset", "veryfast",
                "-c:a", "aac", "-b:a", "96k",
                "-movflags", "+faststart",
                saida,
            ]
            with _recurso_cpu_pesada("ffmpeg-compressao-video"):
                resultado = subprocess.run(
                    cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=300
                )
            if resultado.returncode != 0 or not os.path.exists(saida):
                return conteudo, content_type, None

            with open(saida, "rb") as f:
                conteudo_novo = f.read()
            return conteudo_novo, "video/mp4", ".mp4"
    except Exception:
        return conteudo, content_type, None

def _transcrever_video_whisper(conteudo: bytes) -> str:
    """Extrai o áudio do vídeo (via ffmpeg) e transcreve localmente com o
    Whisper open-source (faster-whisper) — roda na CPU do próprio
    servidor, sem custo de API. Devolve string vazia se o modelo não
    tiver carregado, o ffmpeg não estiver disponível, o vídeo não tiver
    áudio, ou qualquer etapa falhar — nunca quebra o fluxo de
    coleta/análise."""
    _wm = whisper_model_ou_none()
    if _wm is None:
        return ""

    import subprocess
    import tempfile
    import os
    import shutil

    if shutil.which("ffmpeg") is None:
        return ""

    try:
        with tempfile.TemporaryDirectory() as tmp:
            entrada = os.path.join(tmp, "entrada")
            audio = os.path.join(tmp, "audio.wav")
            with open(entrada, "wb") as f:
                f.write(conteudo)

            # extrai só o áudio (mono, 16kHz) — bem menor que o vídeo
            # original e já na taxa de amostragem que o Whisper espera
            cmd = [
                "ffmpeg", "-y", "-i", entrada,
                "-vn", "-ac", "1", "-ar", "16000",
                audio,
            ]
            with _recurso_cpu_pesada("ffmpeg-extracao-audio-whisper"):
                resultado = subprocess.run(
                    cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=180
                )
            if resultado.returncode != 0 or not os.path.exists(audio) or os.path.getsize(audio) == 0:
                return ""  # sem faixa de áudio, ou falha ao extrair

            # Diferente do ffmpeg acima (que roda em subprocess e por isso
            # aceita `timeout` nativo), `whisper_model.transcribe()` roda
            # dentro do próprio processo Python e devolve um GERADOR — a
            # inferência de verdade só acontece quando iteramos nele (no
            # `" ".join(...)` logo abaixo). Sem teto de tempo aqui, um
            # áudio problemático (corrompido, silêncio longo confundindo
            # o VAD, etc.) podia travar essa iteração indefinidamente e
            # segurar pra sempre 1 dos 3 workers do ThreadPoolExecutor que
            # chama esta função — foi isso que deixou uma migração real
            # parada em "32 de 155" por mais de uma hora, mesmo com o
            # progresso ao vivo funcionando certinho (o worker travado
            # nunca chegava a reportar o próximo item).
            #
            # Como não dá pra matar uma thread Python à força, rodamos a
            # transcrição numa thread própria e só ESPERAMOS por ela com
            # prazo: se estourar, desistimos e devolvemos "" (mídia segue
            # sem transcrição, sem quebrar o fluxo) — a thread órfã do
            # Whisper continua rodando sozinha em segundo plano até
            # terminar, mas não bloqueia mais ninguém.
            def _transcrever_sync():
                with _recurso_cpu_pesada("whisper-inferencia"):
                    segmentos, _info = _wm.transcribe(audio, language="pt", vad_filter=True)
                    return " ".join(s.text.strip() for s in segmentos).strip()

            from concurrent.futures import ThreadPoolExecutor as _TPE, TimeoutError as _TimeoutErr
            _timeout_whisper = st.secrets.get("WHISPER_TRANSCRIBE_TIMEOUT_SEGUNDOS", )
            with _TPE(max_workers=1) as _exec_whisper:
                _future = _exec_whisper.submit(_transcrever_sync)
                try:
                    return _future.result(timeout=_timeout_whisper)
                except _TimeoutErr:
                    return ""
    except Exception:
        return ""

def obter_transcricao_video(url_video: str, user_id: str = None) -> str:
    """Devolve a transcrição do vídeo (texto falado, via Whisper), pra
    usar nas análises de IA no lugar de mandar o vídeo em si.

    Prioriza a transcrição já salva na tabela `midias` (feita no momento
    do upload pro R2, ou no reprocessamento). Se não achar nada salvo —
    vídeo ainda não migrado pro R2, por exemplo — transcreve na hora como
    fallback, mas sem persistir (evita segurar a UI esperando salvar)."""
    if not url_video:
        return ""

    cache = st.session_state.setdefault("_cache_transcricoes_video", {})
    if url_video in cache:
        return cache[url_video]

    texto = ""
    try:
        res = supabase.table("midias").select("transcricao").eq("url_cdn", url_video).execute()
        if res.data and (res.data[0].get("transcricao") or "").strip():
            texto = res.data[0]["transcricao"].strip()
    except Exception:
        pass

    if not texto and whisper_model_ou_none() is not None:
        try:
            resp = _http_get(url_video, timeout=30)
            resp.raise_for_status()
            texto = _transcrever_video_whisper(resp.content)
        except Exception:
            texto = ""

    cache[url_video] = texto
    return texto

def _extrair_thumbnail_video(conteudo: bytes):
    """Extrai um frame do vídeo (via ffmpeg) pra usar como imagem de capa —
    permite que a IA "veja" o criativo de anúncios em vídeo, já que o
    Gemini não recebe mais o vídeo em si. Pega o frame em ~1s (evita o
    1º frame, que às vezes é preto/em branco); se o vídeo for mais curto
    que isso, cai pro frame 0. Devolve os bytes em JPEG, ou None se
    algo falhar — nunca quebra o upload."""
    import subprocess
    import tempfile
    import os
    import shutil

    if shutil.which("ffmpeg") is None:
        return None

    for _offset in ("00:00:01", "00:00:00"):
        try:
            with tempfile.TemporaryDirectory() as tmp:
                entrada = os.path.join(tmp, "entrada")
                saida = os.path.join(tmp, "capa.jpg")
                with open(entrada, "wb") as f:
                    f.write(conteudo)

                cmd = [
                    "ffmpeg", "-y",
                    "-ss", _offset, "-i", entrada,
                    "-frames:v", "1", "-q:v", "3",
                    saida,
                ]
                with _recurso_cpu_pesada("ffmpeg-thumbnail"):
                    resultado = subprocess.run(
                        cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60
                    )
                if resultado.returncode == 0 and os.path.exists(saida) and os.path.getsize(saida) > 0:
                    with open(saida, "rb") as f:
                        return f.read()
        except Exception:
            continue
    return None

def _registrar_falha_midia(user_id: str, empresa: str, ad_id: str, tipo: str,
                            url_origem: str, erro) -> None:
    """Registra (ou incrementa) uma falha de download de mídia — guardando
    o número do anúncio (ad_id) — pra dar pra tentar de novo depois em vez
    de o anúncio ficar pra sempre com o link original do Facebook (que
    expira e é isso que aparece pro usuário como "link" no card)."""
    try:
        import datetime as _dt
        existente = (
            supabase.table("midias_falhas")
            .select("id, tentativas")
            .eq("user_id", user_id)
            .eq("url_origem", url_origem)
            .execute()
        )
        if existente.data:
            reg = existente.data[0]
            supabase.table("midias_falhas").update({
                "tentativas":   reg["tentativas"] + 1,
                "ultimo_erro":  str(erro)[:500],
                "atualizado_em": _dt.datetime.now().isoformat(),
            }).eq("id", reg["id"]).execute()
        else:
            supabase.table("midias_falhas").insert({
                "user_id":     user_id,
                "empresa":     empresa,
                "ad_id":       ad_id,
                "tipo":        tipo,
                "url_origem":  url_origem,
                "tentativas":  1,
                "ultimo_erro": str(erro)[:500],
            }).execute()
    except Exception:
        pass  # o log de falha nunca pode derrubar o fluxo principal

def _limpar_falha_midia(user_id: str, url_origem: str) -> None:
    """Remove o registro de falha depois que a mídia finalmente baixou
    com sucesso (seja na primeira tentativa, seja numa retentativa)."""
    try:
        supabase.table("midias_falhas").delete().eq("user_id", user_id).eq("url_origem", url_origem).execute()
    except Exception:
        pass

_REGEX_YOUTUBE = re.compile(
    r"(?:youtube\.com/(?:watch\?(?:.*&)?v=|shorts/)|youtu\.be/)([a-zA-Z0-9_-]{6,20})"
)

def _e_url_youtube(url: str) -> bool:
    """True se a URL for a página /watch (ou shorts, ou youtu.be) do
    YouTube — HTML, não um arquivo de vídeo. Não confundir com
    i.ytimg.com (thumbnail, essa sim é uma imagem de verdade)."""
    return bool(url) and bool(_REGEX_YOUTUBE.search(url))


# persistência definitiva; este cache só evita repetir GETs do mesmo vídeo
# durante uma mesma execução/processo.
_YOUTUBE_CC_CACHE_V150 = {}
_YOUTUBE_CC_LOCK_V150 = threading.Lock() if "threading" in globals() else None

def _youtube_video_id_v150(url: str) -> str:
    m = _REGEX_YOUTUBE.search(url or "")
    return m.group(1) if m else ""

def _achar_caption_tracks_v150(obj):
    """Procura recursivamente `captionTracks` dentro do player response."""
    if isinstance(obj, dict):
        tracks = obj.get("captionTracks")
        if isinstance(tracks, list) and tracks:
            return tracks
        for v in obj.values():
            achou = _achar_caption_tracks_v150(v)
            if achou:
                return achou
    elif isinstance(obj, list):
        for v in obj:
            achou = _achar_caption_tracks_v150(v)
            if achou:
                return achou
    return []

def _extrair_player_response_youtube_v150(html_text: str):
    """Extrai ytInitialPlayerResponse sem depender de biblioteca externa."""
    import json as _json_y150
    decoder = _json_y150.JSONDecoder()
    marcadores = (
        "ytInitialPlayerResponse = ",
        "var ytInitialPlayerResponse = ",
        "window['ytInitialPlayerResponse'] = ",
    )
    for marcador in marcadores:
        pos = html_text.find(marcador)
        if pos < 0:
            continue
        inicio = pos + len(marcador)
        while inicio < len(html_text) and html_text[inicio].isspace():
            inicio += 1
        try:
            obj, _fim = decoder.raw_decode(html_text[inicio:])
            if isinstance(obj, dict):
                return obj
        except Exception:
            pass

    # propriedade JSON. O raw_decode começa exatamente no objeto após a chave.
    for marcador in ('"playerResponse":', '"ytInitialPlayerResponse":'):
        pos = html_text.find(marcador)
        if pos < 0:
            continue
        inicio = pos + len(marcador)
        while inicio < len(html_text) and html_text[inicio].isspace():
            inicio += 1
        try:
            obj, _fim = decoder.raw_decode(html_text[inicio:])
            if isinstance(obj, dict):
                return obj
        except Exception:
            pass
    return {}

def _escolher_track_cc_youtube_v150(tracks):
    """Prioridade: pt-BR manual, pt manual, pt-BR auto, pt auto,
    depois legenda manual em qualquer idioma e, por último, automática."""
    def score(t):
        lang = str(t.get("languageCode") or "").lower()
        auto = str(t.get("kind") or "").lower() == "asr"
        if lang in ("pt-br", "pt_br"):
            base = 0
        elif lang == "pt" or lang.startswith("pt-"):
            base = 10
        else:
            base = 30
        if auto:
            base += 5
        return base
    validas = [t for t in (tracks or []) if t.get("baseUrl")]
    return min(validas, key=score) if validas else None

def _texto_json3_youtube_v150(payload):
    partes = []
    for ev in (payload or {}).get("events", []) or []:
        segs = ev.get("segs") or []
        linha = "".join(str(s.get("utf8") or "") for s in segs)
        linha = " ".join(linha.replace("\n", " ").split())
        if linha:
            partes.append(linha)
    # remove repetições consecutivas comuns em captions segmentadas
    saida = []
    anterior = None
    for p in partes:
        if p != anterior:
            saida.append(p)
        anterior = p
    return " ".join(saida).strip()


def _limpar_texto_legenda_v155(texto: str) -> str:
    """Converte VTT/SRT simples em texto corrido."""
    import re as _re_v155
    linhas=[]
    anterior=None
    for ln in str(texto or "").replace("\r", "\n").split("\n"):
        ln=ln.strip()
        if not ln or ln.upper()=="WEBVTT" or ln.isdigit() or "-->" in ln:
            continue
        if ln.startswith(("NOTE", "Kind:", "Language:")):
            continue
        ln=_re_v155.sub(r"<[^>]+>", "", ln)
        ln=" ".join(ln.split())
        if ln and ln != anterior:
            linhas.append(ln)
            anterior=ln
    return " ".join(linhas).strip()


def _obter_cc_ytdlp_v155(url_video: str, video_id: str) -> dict:
    """Rota principal de CC usando o yt-dlp já instalado no deployment."""
    import glob as _glob_v155
    import json as _json_v155
    import os as _os_v155
    import tempfile as _tempfile_v155

    r={
        "text":"", "language":"", "source":"", "video_id":video_id,
        "url":url_video, "cc_status":"pendente", "cc_reason":"",
        "cc_method":"yt-dlp", "http_status":None,
    }
    try:
        import yt_dlp as _yt_dlp_v155
    except Exception as exc:
        r.update(cc_status="erro_captura", cc_reason=f"yt-dlp indisponível: {exc!r}", cc_method="yt-dlp-import")
        print(f"[YOUTUBE-CC][YTDLP][ERRO] video_id={video_id} import={exc!r}", flush=True)
        return r

    opts={
        "quiet":True, "no_warnings":True, "skip_download":True,
        "noplaylist":True, "socket_timeout":25, "retries":2,
        "extractor_retries":2,
        "extractor_args":{"youtube":{"player_client":["android","ios","web"]}},
    }
    try:
        with _yt_dlp_v155.YoutubeDL(dict(opts)) as ydl:
            info=ydl.extract_info(url_video, download=False) or {}
        manual=info.get("subtitles") or {}
        auto=info.get("automatic_captions") or {}
        print(f"[YOUTUBE-CC][YTDLP][TRACKS] video_id={video_id} manual={sorted(manual)} auto={sorted(auto)}", flush=True)

        def score(lang, is_auto):
            l=str(lang or "").lower().replace("_","-")
            if l == "pt-br": s=0
            elif l == "pt" or l.startswith("pt-"): s=10
            elif l.startswith("en"): s=20
            else: s=30
            return s + (5 if is_auto else 0)

        cands=[]
        cands += [(score(k,False), k, False) for k in manual]
        cands += [(score(k,True), k, True) for k in auto]
        cands.sort(key=lambda x:x[0])
        if not cands:
            r.update(cc_status="sem_cc_confirmado", cc_reason="yt-dlp não encontrou faixas manuais nem automáticas.")
            print(f"[YOUTUBE-CC][YTDLP][SEM-CC] video_id={video_id} motivo=nenhuma_faixa", flush=True)
            return r

        tentativas=[]
        for _, lang, is_auto in cands:
            src_cc="automatic" if is_auto else "manual"
            try:
                with _tempfile_v155.TemporaryDirectory(prefix="ytcc_") as tmp:
                    dlopts=dict(opts)
                    dlopts.update({
                        "outtmpl":_os_v155.path.join(tmp,"%(id)s.%(ext)s"),
                        "writesubtitles":not is_auto,
                        "writeautomaticsub":is_auto,
                        "subtitleslangs":[lang],
                        "subtitlesformat":"json3/vtt/srv1/best",
                    })
                    with _yt_dlp_v155.YoutubeDL(dlopts) as ydl2:
                        ydl2.download([url_video])
                    files=[p for p in _glob_v155.glob(_os_v155.path.join(tmp,"*")) if _os_v155.path.isfile(p)]
                    texto=""
                    arq=""
                    for p in files:
                        raw=Path(p).read_text(encoding="utf-8",errors="ignore")
                        if p.lower().endswith(".json3"):
                            try: texto=_texto_json3_youtube_v150(_json_v155.loads(raw))
                            except Exception: texto=""
                        else:
                            texto=_limpar_texto_legenda_v155(raw)
                        if texto.strip():
                            arq=_os_v155.path.basename(p)
                            break
                    if texto.strip():
                        r.update(text=texto.strip(), language=lang, source=src_cc,
                                 cc_status="com_cc", cc_reason=f"CC capturado pelo yt-dlp ({src_cc}).", cc_method="yt-dlp")
                        print(f"[YOUTUBE-CC][YTDLP][OK] video_id={video_id} lang={lang} source={src_cc} arquivo={arq} chars={len(texto)}", flush=True)
                        return r
                    tentativas.append(f"{lang}:{src_cc}:vazio")
                    print(f"[YOUTUBE-CC][YTDLP][VAZIO] video_id={video_id} lang={lang} source={src_cc} files={[ _os_v155.path.basename(p) for p in files ]}", flush=True)
            except Exception as exc:
                tentativas.append(f"{lang}:{src_cc}:{type(exc).__name__}")
                print(f"[YOUTUBE-CC][YTDLP][ERRO-FAIXA] video_id={video_id} lang={lang} source={src_cc} erro={exc!r}", flush=True)

        r.update(cc_status="erro_captura",
                 cc_reason="yt-dlp encontrou faixa(s), mas não conseguiu baixar o conteúdo: " + "; ".join(tentativas[:12]),
                 language=cands[0][1], source="automatic" if cands[0][2] else "manual")
        return r
    except Exception as exc:
        r.update(cc_status="erro_captura", cc_reason=f"Falha do yt-dlp ao consultar vídeo: {exc!r}")
        print(f"[YOUTUBE-CC][YTDLP][ERRO] video_id={video_id} erro={exc!r}", flush=True)
        return r

def obter_cc_youtube_v150(url_video: str) -> dict:
    """Obtém CC/legenda já disponibilizada pelo YouTube.

    Não baixa o vídeo e não usa Whisper. Retorna:
      text, language, source ('manual' ou 'automatic'), video_id, url
    Em vídeo sem legenda disponível retorna text vazio.
    """
    import json as _json_y150
    import html as _html_y150
    import xml.etree.ElementTree as _ET_y150

    video_id = _youtube_video_id_v150(url_video)
    if not video_id:
        return {"text": "", "language": "", "source": "", "video_id": "", "url": url_video or ""}

    if _YOUTUBE_CC_LOCK_V150:
        with _YOUTUBE_CC_LOCK_V150:
            cached = _YOUTUBE_CC_CACHE_V150.get(video_id)
    else:
        cached = _YOUTUBE_CC_CACHE_V150.get(video_id)

    # {"text": ""} e todas as verificações automáticas seguintes retornavam
    # imediatamente esse vazio sem consultar o YouTube novamente.
    if cached is not None and str(cached.get("text") or "").strip():
        return dict(cached)

    result = {
        "text": "",
        "language": "",
        "source": "",
        "video_id": video_id,
        "url": url_video,
        "cc_status": "pendente",
        "cc_reason": "",
        "cc_method": "",
        "http_status": None,
    }

    _diag_ytdlp_v155 = _obter_cc_ytdlp_v155(url_video, video_id)
    if str(_diag_ytdlp_v155.get("text") or "").strip():
        result.update(_diag_ytdlp_v155)
        if _YOUTUBE_CC_LOCK_V150:
            with _YOUTUBE_CC_LOCK_V150:
                _YOUTUBE_CC_CACHE_V150[video_id] = dict(result)
        else:
            _YOUTUBE_CC_CACHE_V150[video_id] = dict(result)
        print(f"[YOUTUBE-CC][RESULTADO] video_id={video_id} status=com_cc metodo=yt-dlp idioma={result.get('language') or '-'} origem={result.get('source') or '-'} motivo={result.get('cc_reason') or '-'}", flush=True)
        return result

    try:
        watch_url = f"https://www.youtube.com/watch?v={video_id}&hl=pt-BR"
        headers = {
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) "
                "Chrome/124.0.0.0 Safari/537.36"
            ),
            "Accept-Language": "pt-BR,pt;q=0.9,en;q=0.7",
        }
        with _recurso_api_io():
            resp = _http_get(watch_url, timeout=20, headers=headers)
        if resp.status_code == 200 and resp.text:
            player = _extrair_player_response_youtube_v150(resp.text)
            tracks = _achar_caption_tracks_v150(player)
            track = _escolher_track_cc_youtube_v150(tracks)

            if track:
                base_url = _html_y150.unescape(str(track.get("baseUrl") or ""))
                lang = str(track.get("languageCode") or "")
                source = "automatic" if str(track.get("kind") or "").lower() == "asr" else "manual"
                texto_cc = ""

                sep = "&" if "?" in base_url else "?"
                with _recurso_api_io():
                    cap = _http_get(base_url + sep + "fmt=json3", timeout=20, headers=headers)
                if cap.status_code == 200 and cap.text:
                    try:
                        texto_cc = _texto_json3_youtube_v150(cap.json())
                    except Exception:
                        texto_cc = ""

                if not texto_cc:
                    try:
                        with _recurso_api_io():
                            cap_xml = _http_get(base_url, timeout=20, headers=headers)
                        if cap_xml.status_code == 200 and cap_xml.text:
                            root = _ET_y150.fromstring(cap_xml.text)
                            partes = []
                            for node in root.findall(".//text"):
                                val = _html_y150.unescape("".join(node.itertext()))
                                val = " ".join(val.replace("\n", " ").split())
                                if val:
                                    partes.append(val)
                            texto_cc = " ".join(partes).strip()
                    except Exception:
                        texto_cc = ""

                result.update({
                    "text": texto_cc,
                    "language": lang,
                    "source": source if texto_cc else "",
                    "cc_status": "com_cc" if texto_cc else "sem_cc",
                    "cc_reason": "CC capturado pela faixa de legendas do player." if texto_cc else "Faixa de legenda encontrada, mas retornou texto vazio.",
                    "cc_method": "player_captionTracks",
                })

        #
        # O HTML /watch nem sempre expõe captionTracks (consentimento,
        # resposta simplificada, cold start, mudanças do YouTube). Quando a
        # primeira estratégia não encontrou texto, tentamos listar as faixas
        # diretamente e baixar a escolhida.
        if not str(result.get("text") or "").strip():
            try:
                _list_url_v152 = (
                    f"https://www.youtube.com/api/timedtext"
                    f"?type=list&v={video_id}"
                )
                with _recurso_api_io():
                    _list_resp_v152 = _http_get(
                        _list_url_v152,
                        timeout=20,
                        headers=headers,
                    )

                _tracks_v152 = []
                if _list_resp_v152.status_code == 200 and _list_resp_v152.text:
                    try:
                        _root_v152 = _ET_y150.fromstring(_list_resp_v152.text)
                        for _tr_v152 in _root_v152.findall(".//track"):
                            _lang_v152 = (
                                _tr_v152.attrib.get("lang_code")
                                or _tr_v152.attrib.get("lang")
                                or ""
                            )
                            _kind_v152 = _tr_v152.attrib.get("kind") or ""
                            _name_v152 = _tr_v152.attrib.get("name") or ""
                            _tracks_v152.append({
                                "languageCode": _lang_v152,
                                "kind": _kind_v152,
                                "name": {"simpleText": _name_v152},
                                "_timedtext": True,
                            })
                    except Exception:
                        _tracks_v152 = []

                _track_v152 = _escolher_track_cc_youtube_v150([
                    dict(_t_v152, baseUrl="timedtext")
                    for _t_v152 in _tracks_v152
                ])

                if not _track_v152:
                    result.update({
                        "cc_status": "sem_cc",
                        "cc_reason": "YouTube não informou nenhuma faixa de legenda/CC para este vídeo.",
                        "cc_method": "timedtext",
                        "http_status": getattr(_list_resp_v152, "status_code", None),
                    })
                    print(
                        f"[YOUTUBE-CC][SEM-CC] video_id={video_id} "
                        f"motivo=nenhuma_faixa_de_legenda "
                        f"http={getattr(_list_resp_v152, 'status_code', None)}",
                        flush=True,
                    )

                if _track_v152:
                    _lang_v152 = str(
                        _track_v152.get("languageCode") or ""
                    )
                    _kind_v152 = str(_track_v152.get("kind") or "")
                    _source_v152 = (
                        "automatic"
                        if _kind_v152.lower() == "asr"
                        else "manual"
                    )

                    from urllib.parse import urlencode as _urlencode_v152

                    _params_v152 = {
                        "v": video_id,
                        "lang": _lang_v152,
                    }
                    if _kind_v152:
                        _params_v152["kind"] = _kind_v152

                    _cap_url_v152 = (
                        "https://www.youtube.com/api/timedtext?"
                        + _urlencode_v152(_params_v152)
                    )

                    _texto_v152 = ""

                    # Primeiro tenta json3.
                    with _recurso_api_io():
                        _cap_json_v152 = _http_get(
                            _cap_url_v152 + "&fmt=json3",
                            timeout=20,
                            headers=headers,
                        )
                    if (
                        _cap_json_v152.status_code == 200
                        and _cap_json_v152.text
                    ):
                        try:
                            _texto_v152 = _texto_json3_youtube_v150(
                                _cap_json_v152.json()
                            )
                        except Exception:
                            _texto_v152 = ""

                    # Depois XML tradicional.
                    if not _texto_v152:
                        with _recurso_api_io():
                            _cap_xml_v152 = _http_get(
                                _cap_url_v152,
                                timeout=20,
                                headers=headers,
                            )
                        if (
                            _cap_xml_v152.status_code == 200
                            and _cap_xml_v152.text
                        ):
                            try:
                                _root_cap_v152 = _ET_y150.fromstring(
                                    _cap_xml_v152.text
                                )
                                _partes_v152 = []
                                for _node_v152 in _root_cap_v152.findall(
                                    ".//text"
                                ):
                                    _val_v152 = _html_y150.unescape(
                                        "".join(_node_v152.itertext())
                                    )
                                    _val_v152 = " ".join(
                                        _val_v152.replace("\n", " ").split()
                                    )
                                    if _val_v152:
                                        _partes_v152.append(_val_v152)
                                _texto_v152 = " ".join(
                                    _partes_v152
                                ).strip()
                            except Exception:
                                _texto_v152 = ""

                    if _texto_v152:
                        result.update({
                            "text": _texto_v152,
                            "language": _lang_v152,
                            "source": _source_v152,
                            "cc_status": "com_cc",
                            "cc_reason": "CC capturado pelo fallback timedtext.",
                            "cc_method": "timedtext",
                        })
                        print(
                            f"[YOUTUBE-CC] fallback timedtext OK "
                            f"video_id={video_id} lang={_lang_v152} "
                            f"source={_source_v152}",
                            flush=True,
                        )

            except Exception as _exc_fallback_v152:
                result.update({
                    "cc_status": "erro",
                    "cc_reason": f"Erro no fallback timedtext: {_exc_fallback_v152!r}",
                    "cc_method": "timedtext",
                })
                print(
                    f"[YOUTUBE-CC][ERRO] fallback timedtext falhou "
                    f"video_id={video_id}: {_exc_fallback_v152!r}",
                    flush=True,
                )

    except Exception as exc:
        result.update({
            "cc_status": "erro",
            "cc_reason": f"Falha na consulta ao YouTube: {exc!r}",
            "cc_method": result.get("cc_method") or "player",
        })
        print(
            f"[YOUTUBE-CC][ERRO] falha video_id={video_id}: {exc!r}",
            flush=True,
        )

    if str(result.get("text") or "").strip():
        if _YOUTUBE_CC_LOCK_V150:
            with _YOUTUBE_CC_LOCK_V150:
                _YOUTUBE_CC_CACHE_V150[video_id] = dict(result)
        else:
            _YOUTUBE_CC_CACHE_V150[video_id] = dict(result)
    else:
        # Limpa inclusive eventual entrada vazia herdada no mesmo processo.
        if _YOUTUBE_CC_LOCK_V150:
            with _YOUTUBE_CC_LOCK_V150:
                _YOUTUBE_CC_CACHE_V150.pop(video_id, None)
        else:
            _YOUTUBE_CC_CACHE_V150.pop(video_id, None)

    if not str(result.get("text") or "").strip():
        _st_ytdlp_v155 = str((_diag_ytdlp_v155 or {}).get("cc_status") or "")
        if _st_ytdlp_v155 == "erro_captura":
            result.update({
                "cc_status":"erro_captura",
                "cc_reason":(_diag_ytdlp_v155 or {}).get("cc_reason") or "Falha técnica na captura do CC.",
                "cc_method":"yt-dlp+legacy",
                "language":result.get("language") or (_diag_ytdlp_v155 or {}).get("language") or "",
                "source":result.get("source") or (_diag_ytdlp_v155 or {}).get("source") or "",
            })
        elif _st_ytdlp_v155 == "sem_cc_confirmado":
            result.update({
                "cc_status":"sem_cc_confirmado",
                "cc_reason":"yt-dlp não encontrou faixas manuais/automáticas e os fallbacks também não retornaram CC.",
                "cc_method":"yt-dlp+legacy",
            })
        elif result.get("cc_status") == "pendente":
            result.update({
                "cc_status":"erro_captura",
                "cc_reason":"Nenhuma estratégia retornou texto, sem confirmação segura de ausência de CC.",
                "cc_method":result.get("cc_method") or "yt-dlp+legacy",
            })

    print(
        f"[YOUTUBE-CC][RESULTADO] video_id={video_id} "
        f"status={result.get('cc_status')} "
        f"metodo={result.get('cc_method') or '-'} "
        f"idioma={result.get('language') or '-'} "
        f"origem={result.get('source') or '-'} "
        f"motivo={result.get('cc_reason') or '-'}",
        flush=True,
    )

    return result

def _enriquecer_gads_com_cc_youtube_v150(dados: dict) -> dict:
    """Anexa CC do YouTube aos anúncios antes de persistir no gads_cache.

    Campos persistidos no próprio anúncio:
      youtube_video_id
      youtube_url
      video_cc_raw
      video_cc_language
      video_cc_source

    Busca todos os IDs únicos em paralelo (I/O de rede), sem baixar vídeo.
    """
    from concurrent.futures import ThreadPoolExecutor as _TPE_y150

    resultado = {}
    urls_por_id = {}

    for empresa, entry in (dados or {}).items():
        entry_nova = dict(entry)
        ads_novos = [dict(ad) for ad in entry.get("data", [])]
        entry_nova["data"] = ads_novos
        resultado[empresa] = entry_nova

        for ad in ads_novos:
            for u in (ad.get("videos") or []):
                vid = _youtube_video_id_v150(u)
                if vid:
                    urls_por_id.setdefault(vid, u)

    if not urls_por_id:
        return resultado

    cc_por_id = {}
    def _fetch(item):
        vid, url = item
        return vid, obter_cc_youtube_v150(url)

    with _TPE_y150(max_workers=min(4, max(1, len(urls_por_id)))) as ex:
        for vid, info in ex.map(_fetch, list(urls_por_id.items())):
            cc_por_id[vid] = info

    for empresa, entry in resultado.items():
        for ad in entry.get("data", []):
            cc_existente = str(ad.get("video_cc_raw") or "").strip()
            escolhido = None
            escolhido_url = ""
            for u in (ad.get("videos") or []):
                vid = _youtube_video_id_v150(u)
                if not vid:
                    continue
                info = cc_por_id.get(vid) or {}
                if cc_existente:
                    escolhido = {
                        "text": cc_existente,
                        "language": ad.get("video_cc_language") or "",
                        "source": ad.get("video_cc_source") or "",
                        "video_id": ad.get("youtube_video_id") or vid,
                    }
                    escolhido_url = ad.get("youtube_url") or u
                    break
                if (info.get("text") or "").strip():
                    escolhido = info
                    escolhido_url = u
                    break
                if escolhido is None:
                    escolhido = info
                    escolhido_url = u

            if escolhido:
                ad["youtube_video_id"] = escolhido.get("video_id") or _youtube_video_id_v150(escolhido_url)
                ad["youtube_url"] = escolhido_url
                # Só grava os campos de CC quando há conteúdo. Isso distingue
                # "vídeo YouTube sem CC" de "CC encontrado".
                if (escolhido.get("text") or "").strip():
                    ad["video_cc_raw"] = escolhido["text"].strip()
                    ad["video_cc_language"] = escolhido.get("language") or ""
                    ad["video_cc_source"] = escolhido.get("source") or ""

    return resultado


#
# Diferente de uma flag de session_state "já verificado", este controle vive
# no processo e só registra cooldown DEPOIS de uma verificação concluída.
# Se o Streamlit entrar em standby e a execução morrer no meio, o vídeo
# continua sem `video_cc_raw`; no próximo render da página ele será elegível
# novamente para nova tentativa.
_YOUTUBE_CC_VERIFY_ACTIVE_V151 = set()
_YOUTUBE_CC_VERIFY_LAST_OK_V151 = {}
_YOUTUBE_CC_VERIFY_LOCK_V151 = threading.Lock()


_YOUTUBE_CC_STATUS_FINAL_V159 = {
    "com_cc",
    "sem_cc_confirmado",
    "erro_captura",
}


def _youtube_cc_deve_reprocessar_v159(ad: dict) -> bool:
    """
    V159 — evita loop infinito do verificador automático.

    Um anúncio só volta para a fila automática quando:
      - ainda não possui `video_cc_raw`; E
      - ainda não recebeu um estado final nesta coleta.

    `sem_cc_confirmado` e `erro_captura` continuam visíveis nos diagnósticos,
    mas não são reprocessados a cada ciclo de 5 minutos. Uma nova coleta pode
    trazer um anúncio/estado novo e torná-lo elegível novamente.
    """
    if str((ad or {}).get("video_cc_raw") or "").strip():
        return False
    _status = str((ad or {}).get("video_cc_status") or "").strip().lower()
    return _status not in _YOUTUBE_CC_STATUS_FINAL_V159


def _gads_youtube_sem_cc_v151(cache: dict) -> list:
    """Retorna vídeos YouTube realmente pendentes de verificação automática."""
    pendentes = {}
    for _empresa, _entry in (cache or {}).items():
        for _ad in (_entry or {}).get("data", []) or []:
            if not _youtube_cc_deve_reprocessar_v159(_ad):
                continue
            for _url in (_ad.get("videos") or []):
                _vid = _youtube_video_id_v150(_url)
                if _vid:
                    pendentes.setdefault(_vid, _url)
    return list(pendentes.items())


def _atividade_cc_youtube_mais_recente_id_v153(user_id: str):
    """Reaproveita um único card de atividade para verificações de CC YouTube."""
    if not user_id:
        return None
    try:
        _res = (
            supabase.table("atividades")
            .select("id")
            .eq("user_id", user_id)
            .eq("tipo", "cc_youtube")
            .order("criado_em", desc=True)
            .limit(1)
            .execute()
        )
        return _res.data[0]["id"] if _res.data else None
    except Exception:
        return None


def _obter_ou_criar_atividade_cc_youtube_v153(user_id: str, total: int):
    """Cria só o primeiro card; verificações futuras reutilizam e renovam o mesmo."""
    _aid = _atividade_cc_youtube_mais_recente_id_v153(user_id)
    _det = {
        "verificados": 0,
        "total": int(total or 0),
        "salvos": 0,
        "pendentes": int(total or 0),
        "plataforma": "Google Ads",
        "status_visual": "na_fila",
    }
    if _aid:
        atualizar_atividade(_aid, "na_fila", _det)
        return _aid
    return criar_atividade(
        user_id,
        "cc_youtube",
        "Verificando CC dos vídeos do Google Ads",
        _det,
        status="na_fila",
    )


def _carregar_gads_cache_cc_v153(user_id: str) -> dict:
    """Leitura barata do gads_cache para o check global da sidebar."""
    if not user_id:
        return {}
    try:
        _res = _supabase_resiliente(
            lambda: (
                supabase.table("ci_dados")
                .select("gads_cache")
                .eq("user_id", user_id)
                .execute()
            ),
            operacao="carregar_gads_cache_cc",
            tentativas=2,
            backoff=(1, 2),
        )
        return ((_res.data[0].get("gads_cache") or {}) if _res.data else {})
    except Exception:
        return {}


def _gads_youtube_sem_cc_por_empresa_v154(cache: dict) -> dict:
    """Agrupa apenas vídeos realmente pendentes por empresa para lotes menores."""
    _out = {}
    for _empresa, _entry in (cache or {}).items():
        _seen = {}
        for _ad in (_entry or {}).get("data", []) or []:
            if not _youtube_cc_deve_reprocessar_v159(_ad):
                continue
            for _url in (_ad.get("videos") or []):
                _vid = _youtube_video_id_v150(_url)
                if _vid:
                    _seen.setdefault(_vid, _url)
        if _seen:
            _out[_empresa] = list(_seen.items())
    return _out


def _aplicar_resultado_cc_empresa_v154(cache: dict, empresa: str, resultado_por_vid: dict) -> int:
    """Aplica CC e metadados de diagnóstico apenas nos anúncios da empresa."""
    _salvos = 0
    _entry = (cache or {}).get(empresa) or {}
    for _ad in (_entry.get("data") or []):
        _ids_urls = [
            (_youtube_video_id_v150(_u), _u)
            for _u in (_ad.get("videos") or [])
        ]
        for _vid, _url in _ids_urls:
            if not _vid or _vid not in resultado_por_vid:
                continue
            _r = resultado_por_vid[_vid]
            _txt = str(_r.get("text") or "").strip()
            _ad["youtube_video_id"] = _vid
            _ad["youtube_url"] = _url
            _ad["video_cc_status"] = _r.get("cc_status") or ""
            _ad["video_cc_reason"] = _r.get("cc_reason") or ""
            _ad["video_cc_method"] = _r.get("cc_method") or ""
            _ad["video_cc_language"] = _r.get("language") or ""
            _ad["video_cc_source"] = _r.get("source") or ""
            if _txt and not str(_ad.get("video_cc_raw") or "").strip():
                _ad["video_cc_raw"] = _txt
                _salvos += 1
    return _salvos


def _verificar_cc_youtube_background_v151(user_id: str, atividade_id: str = None):
    """
    Reabre o gads_cache diretamente do Supabase, tenta preencher SOMENTE vídeos
    YouTube que continuam sem CC e persiste o cache enriquecido.

    Importante: lê o banco novamente dentro da thread para não sobrescrever
    uma coleta mais nova com um snapshot antigo da sessão.
    """
    import time as _time_cc151

    try:
        _res = _supabase_resiliente(
            lambda: (
                supabase.table("ci_dados")
                .select("gads_cache")
                .eq("user_id", user_id)
                .execute()
            ),
            operacao="verificar_cc_youtube_automatico",
            tentativas=3,
            backoff=(1, 2, 4),
        )
        _cache_atual = (
            (_res.data[0].get("gads_cache") or {})
            if _res.data else {}
        )

        _pendentes_antes = _gads_youtube_sem_cc_v151(_cache_atual)
        if not _pendentes_antes:
            if atividade_id:
                atualizar_atividade(atividade_id, "concluido", {
                    "verificados": 0,
                    "total": 0,
                    "salvos": 0,
                    "pendentes": 0,
                    "plataforma": "Google Ads",
                    "mensagem": "Todos os vídeos do Google Ads já possuem CC disponível no cache.",
                })
            with _YOUTUBE_CC_VERIFY_LOCK_V151:
                _YOUTUBE_CC_VERIFY_LAST_OK_V151[user_id] = _time_cc151.monotonic()
            return

        if atividade_id:
            atualizar_atividade(atividade_id, "em_andamento", {
                "verificados": 0,
                "total": len(_pendentes_antes),
                "salvos": 0,
                "pendentes": len(_pendentes_antes),
                "plataforma": "Google Ads",
            })

        print(
            f"[YOUTUBE-CC-AUTO] verificando {len(_pendentes_antes)} "
            f"vídeo(s) sem CC para user={user_id}",
            flush=True,
        )

        _cache_enriquecido = _cache_atual
        _pend_por_empresa_v154 = _gads_youtube_sem_cc_por_empresa_v154(_cache_atual)
        _total_empresas_v154 = len(_pend_por_empresa_v154)
        _empresa_idx_v154 = 0
        _diag_v154 = {}

        for _empresa_v154, _videos_v154 in _pend_por_empresa_v154.items():
            _empresa_idx_v154 += 1
            print(
                f"[YOUTUBE-CC][EMPRESA] inicio "
                f"empresa={_empresa_v154!r} "
                f"lote={_empresa_idx_v154}/{_total_empresas_v154} "
                f"videos={len(_videos_v154)}",
                flush=True,
            )

            if atividade_id:
                atualizar_atividade(atividade_id, "em_andamento", {
                    "verificados": 0,
                    "total": len(_videos_v154),
                    "salvos": 0,
                    "pendentes": len(_videos_v154),
                    "plataforma": "Google Ads",
                    "empresa": _empresa_v154,
                    "lote_empresa": _empresa_idx_v154,
                    "total_empresas": _total_empresas_v154,
                })

            _resultados_emp_v154 = {}
            for _vid_v154, _url_v154 in _videos_v154:
                print(
                    f"[YOUTUBE-CC][VIDEO] empresa={_empresa_v154!r} "
                    f"video_id={_vid_v154} inicio",
                    flush=True,
                )
                _r_v154 = obter_cc_youtube_v150(_url_v154)
                _resultados_emp_v154[_vid_v154] = _r_v154
                _diag_v154[_vid_v154] = _r_v154

                print(
                    f"[YOUTUBE-CC][VIDEO] empresa={_empresa_v154!r} "
                    f"video_id={_vid_v154} "
                    f"status={_r_v154.get('cc_status')} "
                    f"metodo={_r_v154.get('cc_method') or '-'} "
                    f"motivo={_r_v154.get('cc_reason') or '-'}",
                    flush=True,
                )

            _salvos_emp_v154 = _aplicar_resultado_cc_empresa_v154(
                _cache_enriquecido,
                _empresa_v154,
                _resultados_emp_v154,
            )

            # Persiste ao terminar CADA empresa. Se houver standby depois,
            # as empresas já concluídas não entram de novo no lote.
            _persistir_cache_ads_db(
                user_id,
                "gads_cache",
                _cache_enriquecido,
                tentativas=5,
            )

            _sem_cc_emp_v154 = sum(
                1 for _r in _resultados_emp_v154.values()
                if not str(_r.get("text") or "").strip()
            )
            print(
                f"[YOUTUBE-CC][EMPRESA] fim "
                f"empresa={_empresa_v154!r} "
                f"salvos={_salvos_emp_v154} "
                f"sem_cc={_sem_cc_emp_v154}",
                flush=True,
            )

        # Só persiste se algum CC novo entrou.
        _antes = {
            _vid: str(
                next(
                    (
                        _ad.get("video_cc_raw") or ""
                        for _entry in _cache_atual.values()
                        for _ad in (_entry or {}).get("data", []) or []
                        if _vid in [
                            _youtube_video_id_v150(_u)
                            for _u in (_ad.get("videos") or [])
                        ]
                    ),
                    "",
                )
            ).strip()
            for _vid, _url in _pendentes_antes
        }
        _depois = {}
        for _vid, _url in _pendentes_antes:
            _cc_encontrado = ""
            for _entry in _cache_enriquecido.values():
                for _ad in (_entry or {}).get("data", []) or []:
                    _ids = [
                        _youtube_video_id_v150(_u)
                        for _u in (_ad.get("videos") or [])
                    ]
                    if _vid in _ids:
                        _cc_encontrado = str(_ad.get("video_cc_raw") or "").strip()
                        if _cc_encontrado:
                            break
                if _cc_encontrado:
                    break
            _depois[_vid] = _cc_encontrado

        _novos = [
            _vid for _vid in _depois
            if (not _antes.get(_vid)) and _depois.get(_vid)
        ]

        if _novos:
            _persistir_cache_ads_db(
                user_id,
                "gads_cache",
                _cache_enriquecido,
                tentativas=5,
            )
            print(
                f"[YOUTUBE-CC-AUTO] {len(_novos)} CC(s) novo(s) salvo(s) "
                f"automaticamente.",
                flush=True,
            )
        else:
            print(
                "[YOUTUBE-CC-AUTO] nenhum CC novo nesta rodada; vídeos com "
                "sem_cc_confirmado/erro_captura foram finalizados e não "
                "voltarão automaticamente para a fila nesta coleta.",
                flush=True,
            )

        # de uma tentativa automática. Estados finais sem texto (sem CC real ou
        # erro técnico) não mantêm a atividade aberta indefinidamente.
        _pendentes_depois = len(_gads_youtube_sem_cc_v151(_cache_enriquecido))
        if atividade_id:
            atualizar_atividade(atividade_id, "concluido", {
                "verificados": len(_pendentes_antes),
                "total": len(_pendentes_antes),
                "salvos": len(_novos),
                "pendentes": _pendentes_depois,
                "plataforma": "Google Ads",
            })

        # O cooldown começa somente depois que a verificação chegou ao fim.
        # Falha/standby antes daqui não bloqueia a próxima tentativa.
        with _YOUTUBE_CC_VERIFY_LOCK_V151:
            _YOUTUBE_CC_VERIFY_LAST_OK_V151[user_id] = _time_cc151.monotonic()

    except Exception as _exc_cc151:
        # Não grava LAST_OK: próxima renderização poderá tentar de novo.
        if atividade_id:
            atualizar_atividade(atividade_id, "erro", {
                "verificados": 0,
                "total": 0,
                "salvos": 0,
                "pendentes": 0,
                "plataforma": "Google Ads",
                "motivo": str(_exc_cc151),
            })
        print(
            f"[YOUTUBE-CC-AUTO] falha; será elegível novamente no próximo "
            f"render: {_exc_cc151!r}",
            flush=True,
        )
    finally:
        with _YOUTUBE_CC_VERIFY_LOCK_V151:
            _YOUTUBE_CC_VERIFY_ACTIVE_V151.discard(user_id)


def _recuperar_atividade_cc_youtube_orfa_v161(user_id: str, cache_sessao: dict) -> None:
    """
    Recupera o card de CC que ficou persistido como `em_andamento`
    depois que a thread responsável deixou de existir (restart/redeploy).

    Se ainda houver vídeos realmente pendentes, volta a atividade para a fila.
    Se não houver mais pendências segundo a regra V159, fecha como concluída.
    """
    try:
        _uid = str(user_id or "").strip()
        if not _uid:
            return

        # Se há worker vivo neste processo, a atividade não é órfã.
        with _YOUTUBE_CC_VERIFY_LOCK_V151:
            if _uid in _YOUTUBE_CC_VERIFY_ACTIVE_V151:
                return

        _aid = _atividade_cc_youtube_mais_recente_id_v153(_uid)
        if not _aid:
            return

        _res = (
            supabase.table("atividades")
            .select("id,status,detalhes")
            .eq("id", _aid)
            .limit(1)
            .execute()
        )
        _rows = getattr(_res, "data", None) or []
        if not _rows:
            return

        _row = _rows[0] or {}
        _status_db = str(_row.get("status") or "").strip().lower()
        _det = _row.get("detalhes") or {}
        if not isinstance(_det, dict):
            _det = {}

        _status_visual = str(_det.get("status_visual") or "").strip().lower()
        if _status_db != "em_andamento" and _status_visual != "em_andamento":
            return

        _pendentes = len(_gads_youtube_sem_cc_v151(cache_sessao or {}))
        _det_novo = dict(_det)
        _det_novo["recuperada_v161"] = True
        _det_novo["motivo_recuperacao"] = (
            "Worker anterior não existe mais em memória após restart/redeploy."
        )
        _det_novo["pendentes"] = int(_pendentes)

        if _pendentes > 0:
            _det_novo["status_visual"] = "na_fila"
            atualizar_atividade(_aid, "na_fila", _det_novo)
            print(
                f"[YOUTUBE-CC][RECOVERY-V161] atividade={_aid} user={_uid} "
                f"órfã recuperada -> na_fila; pendentes={_pendentes}",
                flush=True,
            )
        else:
            _det_novo["status_visual"] = "concluido"
            atualizar_atividade(_aid, "concluido", _det_novo)
            print(
                f"[YOUTUBE-CC][RECOVERY-V161] atividade={_aid} user={_uid} "
                "órfã encerrada -> concluido; pendentes=0",
                flush=True,
            )

    except Exception as _e:
        print(
            f"[YOUTUBE-CC][RECOVERY-V161][ERRO] user={user_id} erro={_e!r}",
            flush=True,
        )


def iniciar_verificacao_cc_youtube_automatica_v151(
    user_id: str,
    cache_sessao: dict,
    intervalo_segundos: int = 300,
) -> bool:
    """
    Dispara a recuperação automática se:
      1. há vídeo YouTube sem `video_cc_raw`;
      2. não existe outra verificação ativa para o usuário;
      3. uma verificação concluída não ocorreu nos últimos 5 min.

    Retorna True apenas quando uma nova thread foi iniciada.
    """
    import time as _time_cc151

    _recuperar_atividade_cc_youtube_orfa_v161(user_id, cache_sessao)

    if not user_id or not _gads_youtube_sem_cc_v151(cache_sessao):
        return False

    _agora = _time_cc151.monotonic()
    with _YOUTUBE_CC_VERIFY_LOCK_V151:
        if user_id in _YOUTUBE_CC_VERIFY_ACTIVE_V151:
            return False

        _ultimo_ok = float(_YOUTUBE_CC_VERIFY_LAST_OK_V151.get(user_id) or 0)
        if _ultimo_ok and (_agora - _ultimo_ok) < float(intervalo_segundos):
            return False

        _YOUTUBE_CC_VERIFY_ACTIVE_V151.add(user_id)

    _total_pendente_v153 = len(_gads_youtube_sem_cc_v151(cache_sessao))
    _atividade_cc_v153 = _obter_ou_criar_atividade_cc_youtube_v153(
        user_id,
        _total_pendente_v153,
    )

    _thread = threading.Thread(
        target=_verificar_cc_youtube_background_v151,
        args=(user_id, _atividade_cc_v153),
        daemon=True,
        name=f"youtube-cc-auto-{str(user_id)[:8]}",
    )
    _thread.start()
    return True

def baixar_e_persistir_midia(url_origem: str, user_id: str, empresa: str,
                              tipo: str = "imagem", ad_id: str = None,
                              referer_hint: str = "") -> str:
    """Baixa a mídia de url_origem (link do Facebook/Instagram/Google, que
    expira) e sobe pro Cloudflare R2. Retorna a URL permanente pra usar no
    lugar da original. Se o R2 não estiver configurado, o plano não
    permitir, ou o download falhar por qualquer motivo, devolve a própria
    url_origem — nunca quebra o fluxo existente.

    `referer_hint`: URL da página do anúncio (ex.: snapshot_url do Google
    Ads), usada como último recurso de Referer quando a mídia é do Google.
    Sem isso, essa função usava um Referer fixo de facebook.com pra
    QUALQUER mídia — certo pra imagem/vídeo da Meta, mas errado pra
    imagem do Google (tpc.googlesyndication.com): um Referer de
    facebook.com numa URL do Google é mais suspeito pro CDN do que
    nenhum Referer, e o download vinha falhando silenciosamente (a
    mídia nunca migrava pro R2, ficava com o link cru do Google, que
    depois falha de novo no <img> do navegador por hotlink/referrer —
    resultado: card sem imagem mesmo quando a coleta achou a URL certa
    e conseguiu baixar ela em outra etapa, como o base64 pra IA)."""
    if not url_origem or not url_origem.startswith("http"):
        return url_origem
    if R2_PUBLIC_BASE and url_origem.startswith(R2_PUBLIC_BASE):
        return url_origem  # já é uma mídia nossa no R2 — nada a fazer
    if r2_client is None:
        return url_origem
    if not pode_baixar_midia(user_id):
        return url_origem

    # V93: reaproveita uma URL de origem que já foi persistida antes SEM
    # baixar o arquivo novamente. O dedupe antigo era apenas por hash e,
    # portanto, só descobria a duplicata depois de gastar uma requisição ao
    # CDN da Meta/Google. Como URLs da Meta podem se repetir entre anúncios
    # da mesma coleta, este atalho elimina downloads desnecessários.
    try:
        _por_origem = (
            supabase.table("midias")
            .select("url_cdn")
            .eq("user_id", user_id)
            .eq("url_origem", url_origem)
            .execute()
        )
        if _por_origem.data:
            _url_existente = _por_origem.data[0].get("url_cdn")
            if _url_existente:
                return _url_existente
    except Exception:
        pass

    # Teto de tentativas — sem isso, QUALQUER chamador (a varredura
    # automática inclusive) tentava de novo pra sempre, mesmo pra uma
    # URL que já provou repetidamente que não vai baixar (ex: 403 do
    # CDN de vídeo do Facebook, que não é falha passageira).
    try:
        _falha_existente = (
            supabase.table("midias_falhas")
            .select("tentativas")
            .eq("user_id", user_id)
            .eq("url_origem", url_origem)
            .execute()
        )
        if _falha_existente.data and _falha_existente.data[0]["tentativas"] >= MAX_TENTATIVAS_MIDIA:
            return url_origem
    except Exception:
        pass  # se a checagem falhar, segue tentando normalmente

    try:
        _user_agent = (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
            "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
        )
        _e_midia_google = "googlesyndication.com" in url_origem or "googleusercontent.com" in url_origem
        _e_youtube = _e_url_youtube(url_origem)

        if _e_youtube:
            # Vídeo de anúncio do Google Ads: o "vídeo" é, na verdade, o
            # próprio link do YouTube (youtube.com/watch?v=...), não um
            # arquivo baixável com um GET simples. Não baixamos mais o
            # vídeo de verdade aqui (isso exigia yt-dlp) — o link do
            # YouTube não expira como os da Meta, então simplesmente
            # devolve a própria url_origem sem tentar migrar pro R2; o
            # player do card (aba Google Ads) já sabe reconhecer esse
            # caso e abrir o embed oficial do YouTube.
            return url_origem
        else:
            if _e_midia_google:
                # CDN do Google (tpc.googlesyndication.com) — igual em
                # _url_para_base64 (aba Google Ads): um Referer forjado pode
                # ser mais suspeito pro CDN do que nenhum Referer, então tenta
                # em ordem, da tentativa mais "limpa" (sem headers) até a mais
                # específica (a própria página do criativo, quando temos).
                _tentativas_headers = [
                    {},
                    {"User-Agent": _user_agent},
                    {"User-Agent": _user_agent, "Referer": "https://adstransparency.google.com/"},
                ]
                if referer_hint:
                    _tentativas_headers.append({"User-Agent": _user_agent, "Referer": referer_hint})
            else:
                # Meta/Instagram (comportamento original) — o link expira, mas
                # é servido pelo CDN da Meta esperando um Referer de facebook.com.
                _tentativas_headers = [
                    {"User-Agent": _user_agent, "Referer": "https://www.facebook.com/", "Accept": "*/*"},
                ]

            resp = None
            for _i_tent, _headers_download in enumerate(_tentativas_headers):
                try:
                    with _recurso_api_io():
                        _tentativa = _http_get(url_origem, timeout=15, stream=True, headers=_headers_download)
                except Exception as _e_tent:
                    print(f"[MIDIA-DL:{ad_id}] tentativa={_i_tent} headers={list(_headers_download.keys())} EXCEÇÃO: {_e_tent!r}", flush=True)
                    continue
                _ct_tentativa = (_tentativa.headers.get("content-type", "") or "").split(";")[0].strip()
                print(
                    f"[MIDIA-DL:{ad_id}] tentativa={_i_tent} headers={list(_headers_download.keys())} "
                    f"url={url_origem} status={_tentativa.status_code} content-type={_ct_tentativa!r} "
                    f"bytes={len(_tentativa.content) if _tentativa.content else 0}",
                    flush=True,
                )
                # Validação de content-type pra QUALQUER origem (não só
                # Google) — sem isso, uma resposta 200 com HTML/erro no
                # corpo (ex.: página do YouTube, ou uma página de erro
                # genérica de qualquer CDN) passava como "sucesso" e subia
                # pro R2 disfarçada de imagem/vídeo.
                if _tentativa.status_code == 200 and _tentativa.content and _ct_tentativa.startswith(("image/", "video/")):
                    resp = _tentativa
                    print(f"[MIDIA-DL:{ad_id}] SUCESSO na tentativa={_i_tent}", flush=True)
                    break
            if resp is None:
                print(f"[MIDIA-DL:{ad_id}] TODAS as {len(_tentativas_headers)} tentativas falharam pra {url_origem} — mantém link original", flush=True)
                # Nenhuma tentativa deu certo (nem status 200+content-type
                # válido) — levanta pra cair no except abaixo, que registra
                # a falha (alimenta MAX_TENTATIVAS_MIDIA) e devolve a
                # url_origem sem quebrar o fluxo.
                raise RuntimeError(f"download falhou em todas as {len(_tentativas_headers)} tentativas (status/content-type inválido)")
            conteudo = resp.content
            content_type = (
                resp.headers.get("content-type", "")
                or mimetypes.guess_type(url_origem)[0]
                or "application/octet-stream"
            )
        hash_conteudo = hashlib.sha256(conteudo).hexdigest()

        # dedupe: mesma mídia já baixada antes pra esse usuário → reaproveita,
        # MAS só depois de confirmar que o arquivo ainda existe de verdade no
        # bucket. Sem essa checagem, se um arquivo for removido por qualquer
        # motivo (ex: uma corrida durante o reprocessamento), o dedupe ficava
        # devolvendo esse link morto pra sempre, pra qualquer anúncio novo
        # que reusasse a mesma imagem (comum em anúncios "Dinâmicos", que
        # repetem o mesmo criativo em vários cards).
        existente = (
            supabase.table("midias")
            .select("url_cdn")
            .eq("user_id", user_id)
            .eq("hash_conteudo", hash_conteudo)
            .execute()
        )
        if existente.data:
            _url_dedupe = existente.data[0]["url_cdn"]
            try:
                with _recurso_api_io():
                    _check = _http_head(_url_dedupe, timeout=5)
                _arquivo_existe = _check.status_code == 200
            except Exception:
                _arquivo_existe = False
            if _arquivo_existe:
                _limpar_falha_midia(user_id, url_origem)
                return _url_dedupe
            # arquivo sumiu do bucket apesar do registro no banco — remove
            # a linha órfã e segue pro upload normal abaixo, como se não
            # tivesse achado dedupe nenhum.
            try:
                supabase.table("midias").delete().eq("user_id", user_id).eq("hash_conteudo", hash_conteudo).execute()
            except Exception:
                pass

        ext = mimetypes.guess_extension(content_type.split(";")[0].strip()) or ""
        conteudo_upload, content_type_upload = conteudo, content_type
        transcricao_video = ""
        thumbnail_url = ""

        if tipo == "imagem":
            conteudo_upload, content_type_upload, ext_comprimida = _comprimir_imagem(conteudo, content_type)
            if ext_comprimida:
                ext = ext_comprimida
        elif tipo == "video":
            conteudo_upload, content_type_upload, ext_comprimida = _comprimir_video(conteudo, content_type)
            if ext_comprimida:
                ext = ext_comprimida
            # Transcrição NÃO roda mais aqui. Antes, cada vídeo migrado podia
            # segurar um dos workers da migração por até alguns minutos
            # (ffmpeg + Whisper na CPU), fazendo a barra "X de Y salvos"
            # andar bem mais devagar do que o download/upload em si
            # precisaria. transcricao_video fica "" (vira NULL no banco,
            # ver insert abaixo) e é isso que sinaliza "pendente" pra fila
            # separada em _transcrever_pendentes_background — que roda
            # depois de terminar a migração, sem bloquear o progresso dela.

        storage_key = f"{user_id}/{_slug_empresa(empresa)}/{hash_conteudo}{ext}"

        r2_client.put_object(
            Bucket=R2_BUCKET,
            Key=storage_key,
            Body=conteudo_upload,
            ContentType=content_type_upload,
        )
        url_cdn = f"{R2_PUBLIC_BASE}/{storage_key}"

        if tipo == "video":
            frame_capa = _extrair_thumbnail_video(conteudo_upload)
            if frame_capa:
                storage_key_thumb = f"{user_id}/{_slug_empresa(empresa)}/{hash_conteudo}_capa.jpg"
                try:
                    r2_client.put_object(
                        Bucket=R2_BUCKET,
                        Key=storage_key_thumb,
                        Body=frame_capa,
                        ContentType="image/jpeg",
                    )
                    thumbnail_url = f"{R2_PUBLIC_BASE}/{storage_key_thumb}"
                except Exception:
                    thumbnail_url = ""

        supabase.table("midias").insert({
            "user_id":       user_id,
            "empresa":       empresa,
            "ad_id":         ad_id,
            "tipo":          tipo,
            "url_origem":    url_origem,
            "storage_key":   storage_key,
            "url_cdn":       url_cdn,
            "mime_type":     content_type_upload,
            "tamanho_bytes": len(conteudo_upload),
            "hash_conteudo": hash_conteudo,
            "transcricao":   transcricao_video or None,
            "thumbnail_url": thumbnail_url or None,
        }).execute()

        _limpar_falha_midia(user_id, url_origem)
        return url_cdn
    except Exception as e:
        _registrar_falha_midia(user_id, empresa, ad_id, tipo, url_origem, e)
        return url_origem

def persistir_midias_de_ads(dados: dict, user_id: str, atividade_id: str = None, plataforma: str = "Meta Ads"):
    """Percorre um dict no formato do ads_cache e substitui as URLs de
    imagens/vídeos por versões permanentes no R2, quando possível.
    Usado logo antes de salvar no Supabase, pra nunca persistir um link
    do Facebook que vai expirar.

    Os downloads de imagem são I/O-bound (rede); os de vídeo rodam ffmpeg
    (compressão + thumbnail) — CPU, mas rápido (segundos). A transcrição
    via Whisper, que era o trabalho pesado de verdade (podia segurar um
    worker por minutos), NÃO roda mais aqui — foi movida pra uma fila
    separada depois da migração (ver _transcrever_pendentes_background),
    então o pool pode ser maior sem repetir o erro de SO ("Resource
    temporarily unavailable", Errno 11) que vários ffmpeg+Whisper
    concorrentes causavam antes.

    Se `atividade_id` for passado, grava progresso "ao vivo" nos detalhes
    da atividade (a cada item concluído, com um teto de frequência) —
    é isso que permite a barra de progresso no sino atualizar sozinha
    enquanto a passada ainda está rodando, tipo a barra de cópia de
    arquivos do Windows, em vez de só pular quando a passada inteira
    termina. Os números gravados durante a corrida são uma contagem de
    itens já processados (sucesso ou falha) — uma aproximação honesta de
    "quanto já andou" pra dar feedback em tempo real; o número final
    definitivo de migrados-de-verdade só é conhecido (e gravado) no fim
    da passada, então pode ajustar pra baixo se algum item falhar.

    Devolve (resultado, stats) — stats traz quantos itens não foram
    migrados (falha de rede/ffmpeg, ou bloqueio por cota do plano),
    pra isso nunca mais ficar escondido dentro de um "Concluído". Também
    traz um log por ANÚNCIO (não por URL de mídia) de quem migrou com
    sucesso (anuncios_migrados) e quem deu erro (anuncios_com_erro), cada
    um com id + título, pra alimentar o "mais informações" da atividade
    no sino de notificações."""
    if r2_client is None:
        print("[OCR-DEBUG] persistir_midias_de_ads SAIU CEDO: r2_client is None — nenhuma mídia será migrada/inserida em `midias`", flush=True)
        return dados, {"total": 0, "nao_migrados": 0, "anuncios_com_erro": [], "total_anuncios_com_erro": 0, "anuncios_migrados": [], "total_anuncios_migrados": 0}

    from concurrent.futures import ThreadPoolExecutor
    import threading
    from urllib.parse import urlsplit

    resultado = {}
    tarefas_brutas = []  # referências de campos antes da deduplicação V93

    def _chave_asset(url: str, tipo: str) -> str:
        """Identifica o mesmo asset apesar dos query params temporários da Meta.
        O pathname preserva o nome/id físico do arquivo; parâmetros `_nc_*`,
        `oh`, `oe`, `stp` etc. não entram na chave. Para origens desconhecidas,
        usa a URL completa para não juntar arquivos diferentes por engano.
        """
        if not url:
            return f"{tipo}:vazio"
        try:
            ps = urlsplit(url)
            host = (ps.hostname or "").lower()
            if any(x in host for x in ("fbcdn.net", "facebook.com", "instagram.com")):
                return f"{tipo}:meta:{ps.path}"
        except Exception:
            pass
        return f"{tipo}:url:{url}"

    def _score_url(url: str, tipo: str) -> int:
        """Prefere vídeo/original e evita thumbnail s60 quando há alternativa."""
        u = (url or "").lower()
        if tipo == "video":
            return 1000
        score = 100
        if "s60x60" in u or "_s60" in u:
            score -= 90
        elif "s600x600" in u or "_s600" in u:
            score += 20
        elif "stp=" not in u:
            score += 40  # em geral é a variante original/maior
        return score

    for empresa, entry in dados.items():
        entry_nova = dict(entry)
        ads_novos = [dict(ad) for ad in entry.get("data", [])]
        entry_nova["data"] = ads_novos
        resultado[empresa] = entry_nova

        for ad_idx, ad in enumerate(ads_novos):
            ad_id = ad.get("id")
            # Rótulo legível do anúncio pro log de "quais anúncios foram
            # migrados"/"quais deram erro" — sem isso o log só teria URLs
            # de imagem/vídeo cruas, que não dizem nada pro usuário sobre
            # qual anúncio é qual na tela de "mais informações".
            _titulo_ad = (
                (ad.get("title") or "").strip()
                or (ad.get("body") or "").strip()[:60]
                or (f"Anúncio {ad_id}" if ad_id else "Anúncio sem título")
            )
            # snapshot_url = página do criativo (Central de Transparência
            # do Google, quando é um anúncio do Google Ads) — usada como
            # Referer de último recurso em baixar_e_persistir_midia, pra
            # imagens do Google que só carregam com o Referer exato da
            # página do próprio anúncio (ver comentário na função).
            _referer_hint_ad = ad.get("snapshot_url") or ""
            for url_idx, u in enumerate(ad.get("images") or []):
                tarefas_brutas.append((empresa, ad_idx, "images", url_idx, u, "imagem", ad_id, _titulo_ad, _referer_hint_ad))
            # "carousel_images" (1 imagem por card do carrossel, sem as
            # duplicatas boa/ruim que "images" carrega) também precisa virar
            # link permanente — sem isso, anúncios novos ficariam certos por
            # ora mas com URL crua da Meta, que expira em algumas semanas e
            # quebraria o modal do carrossel mais pra frente.
            for url_idx, u in enumerate(ad.get("carousel_images") or []):
                tarefas_brutas.append((empresa, ad_idx, "carousel_images", url_idx, u, "imagem", ad_id, _titulo_ad, _referer_hint_ad))
            for url_idx, u in enumerate(ad.get("videos") or []):
                tarefas_brutas.append((empresa, ad_idx, "videos", url_idx, u, "video", ad_id, _titulo_ad, _referer_hint_ad))
            # Foto de perfil da página — é a mesma URL pra todo anúncio
            # dessa empresa, mas o dedupe por hash já evita subir de novo;
            # sem isso, esse campo nunca passava pelo R2 e continuava
            # dependendo do link do Facebook, que expira.
            _foto_perfil = ad.get("page_profile_picture")
            if _foto_perfil:
                tarefas_brutas.append((empresa, ad_idx, "page_profile_picture", 0, _foto_perfil, "imagem", ad_id, _titulo_ad, _referer_hint_ad))

    if not tarefas_brutas:
        return resultado, {"total": 0, "nao_migrados": 0, "anuncios_com_erro": [], "total_anuncios_com_erro": 0, "anuncios_migrados": [], "total_anuncios_migrados": 0, "assets_encontrados": 0, "assets_unicos": 0, "duplicados_ignorados": 0, "reutilizados_biblioteca": 0}

    # V93: uma única transferência por asset. Todas as ocorrências do mesmo
    # arquivo (images/carousel/profile e anúncios diferentes) recebem depois
    # a mesma URL permanente. Isso evita baixar s60 + s600 + original do mesmo
    # arquivo e evita repetir a foto de perfil em cada anúncio.
    _grupos = {}
    for t in tarefas_brutas:
        empresa, ad_idx, campo, url_idx, u, tipo, ad_id, titulo_ad, referer_hint = t
        chave = _chave_asset(u, tipo)
        g = _grupos.setdefault(chave, {"refs": [], "melhor": t})
        g["refs"].append(t)
        if _score_url(u, tipo) > _score_url(g["melhor"][4], tipo):
            g["melhor"] = t

    # V98 — além do dedupe desta execução, consulta mídias já salvas em
    # o pathname do asset; se a chave canônica já possui url_cdn, não baixa
    # novamente.
    _cdn_existente_por_chave = {}
    try:
        _res_midias_exist = _supabase_resiliente(
            lambda: supabase.table("midias")
                    .select("url_origem,url_cdn,tipo")
                    .eq("user_id", user_id).execute(),
            operacao="indice_midias_existentes",
            tentativas=3,
        )
        for _m_exist in (_res_midias_exist.data or []):
            _u_exist = _m_exist.get("url_origem") or ""
            _cdn_exist = _m_exist.get("url_cdn") or ""
            _tipo_exist = _m_exist.get("tipo") or ("video" if _e_url_video(_u_exist) else "imagem")
            if _u_exist and _cdn_exist:
                _cdn_existente_por_chave[_chave_asset(_u_exist, _tipo_exist)] = _cdn_exist
    except Exception as _exc_indice:
        print(f"[MIDIA-DEBUG] índice prévio indisponível: {_exc_indice!r}", flush=True)

    tarefas = []
    reutilizados_biblioteca = 0
    for chave, g in _grupos.items():
        _cdn_previo = _cdn_existente_por_chave.get(chave)
        if _cdn_previo:
            reutilizados_biblioteca += 1
            for _ref in g["refs"]:
                _emp, _idx, _campo, _url_idx, _u, _tipo, _aid, _titulo, _rh = _ref
                if _campo == "page_profile_picture":
                    resultado[_emp]["data"][_idx][_campo] = _cdn_previo
                else:
                    resultado[_emp]["data"][_idx][_campo][_url_idx] = _cdn_previo
            continue
        melhor = g["melhor"]
        tarefas.append((*melhor, chave))

    total_assets_encontrados = len(tarefas_brutas)
    total_tarefas = len(tarefas)
    duplicados_ignorados = total_assets_encontrados - len(_grupos)
    print(
        f"[MIDIA-DEBUG] assets={total_assets_encontrados} novos_unicos={total_tarefas} "
        f"duplicados_execucao={duplicados_ignorados} reutilizados_biblioteca={reutilizados_biblioteca}",
        flush=True
    )

    # Lock protege o contador de progresso (vários workers do
    # ThreadPoolExecutor terminam "ao mesmo tempo") e o timestamp da
    # última escrita no Supabase, que usamos pro throttle abaixo.
    _lock_progresso = threading.Lock()
    _estado_progresso = {"concluidas": 0, "ultima_escrita": 0.0}
    INTERVALO_MIN_ESCRITA_PROGRESSO = 1.5  # segundos entre updates no banco

    # Nome da empresa (e plataforma) pra incluir em toda escrita de
    # progresso — precisa ser regravado sempre porque atualizar_atividade
    # substitui o dict de detalhes inteiro (não faz merge); sem isso, a
    # primeira atualização de progresso ao vivo apagaria os campos
    # "empresa"/"plataforma" que o botão Continuar/Refazer E o dedup de
    # iniciar_migracao_midia_background (_atividade_migracao_mais_
    # recente_id) dependem pra saber qual empresa/plataforma essa
    # atividade é — perder "plataforma" aqui fazia o dedup nunca achar
    # essa atividade de novo (caía no default "Meta Ads") e criar um
    # CARD NOVO pra mesma empresa a cada verificação de segurança.
    # `dados` sempre tem uma única empresa quando atividade_id é passado
    # (é assim que _migrar_midia_background chama esta função).
    _empresa_progresso = next(iter(dados), None)

    def _reportar_progresso_live(concluidas: int):
        if not atividade_id:
            return
        import time as _t_prog
        agora = _t_prog.time()
        with _lock_progresso:
            e_ultima = concluidas >= total_tarefas
            if not e_ultima and (agora - _estado_progresso["ultima_escrita"] < INTERVALO_MIN_ESCRITA_PROGRESSO):
                return
            _estado_progresso["ultima_escrita"] = agora
        atualizar_atividade(atividade_id, "em_andamento", {
            "empresa": _empresa_progresso,
            "plataforma": plataforma,
            "migradas": concluidas,
            "total": total_tarefas,
            "aviso": f"Migrando agora — {concluidas} de {total_tarefas} anúncios processados nesta passada.",
            "ultima_tentativa_em": _agora_iso(),
        })

    def _processar(t):
        empresa, ad_idx, campo, url_idx, u, tipo, ad_id, titulo_ad, referer_hint, chave_asset = t
        nova_url = baixar_e_persistir_midia(u, user_id, empresa, tipo, ad_id, referer_hint)
        # "não migrado" = a URL não mudou E não é porque já era do R2
        # (nesse caso o não-mudou é intencional, não uma falha)
        ja_era_r2 = bool(R2_PUBLIC_BASE) and u.startswith(R2_PUBLIC_BASE)
        # V87: vídeo do Google Ads hospedado no YouTube é uma mídia externa
        # permanente, não uma falha. `baixar_e_persistir_midia` devolve a URL
        # original de propósito (não usamos yt-dlp). Antes isso era contado
        # como `nao_migrado` e o card mostrava metade dos vídeos como erro.
        _externo_permanente = (tipo == "video" and _e_url_youtube(u))
        nao_migrado = (nova_url == u) and not ja_era_r2 and not _externo_permanente
        with _lock_progresso:
            _estado_progresso["concluidas"] += 1
            _concluidas_agora = _estado_progresso["concluidas"]
        _reportar_progresso_live(_concluidas_agora)
        return (empresa, ad_idx, campo, url_idx, nova_url, nao_migrado, u, ad_id, titulo_ad, chave_asset)

    # ── Heartbeat independente de tarefa concluída ──
    # _reportar_progresso_live só grava quando um item TERMINA. Com vídeo
    # (ffmpeg + Whisper), um único item pode levar bem mais que os 90s que
    # _migracao_travada usa como limiar — se os 3 workers caem todos em
    # itens lentos ao mesmo tempo, nenhum progresso é escrito por um bom
    # tempo, e o heurístico de "travado" errava, achando que não tinha
    # nenhuma thread rodando (e mostrando o botão "Continuar" no meio de
    # uma migração que seguia ativa — o usuário clicava nele sem precisar,
    # disparando um refazer_migracao_midia duplicado). Esse heartbeat gira
    # sozinho a cada ~20s, independente de qualquer item ter terminado, só
    # pra provar "ainda tem thread viva aqui".
    INTERVALO_HEARTBEAT_SEGUNDOS = 20
    _heartbeat_stop = threading.Event()

    def _heartbeat_loop():
        if not atividade_id:
            return
        while not _heartbeat_stop.wait(INTERVALO_HEARTBEAT_SEGUNDOS):
            with _lock_progresso:
                _concluidas_hb = _estado_progresso["concluidas"]
            try:
                atualizar_atividade(atividade_id, "em_andamento", {
                    "empresa": _empresa_progresso,
                    "plataforma": plataforma,
                    "migradas": _concluidas_hb,
                    "total": total_tarefas,
                    "aviso": f"Migrando agora — {_concluidas_hb} de {total_tarefas} anúncios processados nesta passada.",
                    "ultima_tentativa_em": _agora_iso(),
                    "ultimo_heartbeat_em": _agora_iso(),
                })
            except Exception:
                pass  # heartbeat é best-effort — uma falha isolada não pode derrubar a migração

    _heartbeat_thread = None
    if atividade_id:
        _heartbeat_thread = threading.Thread(target=_heartbeat_loop, daemon=True)
        _heartbeat_thread.start()

    nao_migrados = []
    ads_com_erro = {}    # ad_id -> título, pelo menos 1 mídia falhou
    ads_migrados = {}    # ad_id -> título, pelo menos 1 mídia migrou com sucesso
    try:
        # Migração pesada serial: um asset por vez. O limite configurável de
        # downloads continua existindo para outros fluxos leves, mas aqui não
        # permitimos fan-out de threads porque esta rotina convive com imagens,
        # vídeos, ffmpeg e buffers grandes no processo principal.
        with ThreadPoolExecutor(max_workers=1) as executor:
            for empresa, ad_idx, campo, url_idx, nova_url, nao_migrado, url_original, ad_id, titulo_ad, chave_asset in executor.map(_processar, tarefas):
                # Propaga o resultado para TODAS as referências equivalentes
                # do asset, inclusive variantes s60/s600/original.
                for _ref in _grupos[chave_asset]["refs"]:
                    _emp, _idx, _campo, _url_idx, _u, _tipo, _aid, _titulo, _rh = _ref
                    if _campo == "page_profile_picture":
                        resultado[_emp]["data"][_idx][_campo] = nova_url
                    else:
                        resultado[_emp]["data"][_idx][_campo][_url_idx] = nova_url
                    if nao_migrado:
                        if _aid:
                            ads_com_erro[_aid] = _titulo
                    elif _aid:
                        ads_migrados[_aid] = _titulo
                if nao_migrado:
                    nao_migrados.append(url_original)
    finally:
        _heartbeat_stop.set()
        if _heartbeat_thread:
            _heartbeat_thread.join(timeout=2)

    # Um mesmo anúncio pode ter, por exemplo, a imagem migrada mas o vídeo
    # não — nesse caso ele conta só como "com erro" no log (não também como
    # "migrado"), pra não esconder que esse anúncio específico ainda tem
    # pendência.
    for _aid in list(ads_migrados):
        if _aid in ads_com_erro:
            del ads_migrados[_aid]

    # Cap na amostra gravada nos detalhes da atividade (jsonb no Supabase) —
    # uma empresa com milhares de anúncios não deve virar um payload gigante
    # a cada atualização de progresso. O total real (sem cap) fica em
    # total_anuncios_com_erro/total_anuncios_migrados.
    LIMITE_AMOSTRA_LOG_ANUNCIOS = 30
    stats = {
        "total": len(tarefas),
        "nao_migrados": len(nao_migrados),
        "amostra_nao_migrados": nao_migrados[:5],
        "anuncios_com_erro": [{"id": k, "titulo": v} for k, v in list(ads_com_erro.items())[:LIMITE_AMOSTRA_LOG_ANUNCIOS]],
        "total_anuncios_com_erro": len(ads_com_erro),
        "anuncios_migrados": [{"id": k, "titulo": v} for k, v in list(ads_migrados.items())[:LIMITE_AMOSTRA_LOG_ANUNCIOS]],
        "total_anuncios_migrados": len(ads_migrados),
        "assets_encontrados": total_assets_encontrados,
        "assets_unicos": total_tarefas,
        "duplicados_ignorados": duplicados_ignorados,
        "reutilizados_biblioteca": reutilizados_biblioteca,
    }
    return resultado, stats

# ---------------------------------------------------
#  TRANSCRIÇÃO DE VÍDEO EM BACKGROUND (desacoplada da migração)
# ---------------------------------------------------
# Antes, a transcrição via Whisper rodava DENTRO de baixar_e_persistir_midia,
# no meio da migração de mídia — cada vídeo podia segurar um dos workers
# do ThreadPoolExecutor por até alguns minutos (ffmpeg + Whisper na CPU),
# fazendo a barra "X de Y anúncios salvos" andar bem mais devagar do que
# o download/upload em si precisaria (o próprio código já tinha um
# comentário registrando que isso deixou uma migração real travada em
# "32 de 155" por mais de uma hora). Agora a migração só baixa, comprime
# e sobe a mídia pro R2 — rápido, principalmente I/O-bound — e a
# transcrição roda depois, numa fila própria, sem bloquear o progresso.
#
# A fila processa os vídeos já migrados (url_cdn no R2, então nunca
# expira) que ainda estão com `transcricao` NULL no banco. Cada vídeo
# ainda passa pelo mesmo teto de tempo por item (ver
# WHISPER_TRANSCRIBE_TIMEOUT_SEGUNDOS dentro de _transcrever_video_whisper)
# — só que agora atrasar a transcrição de um vídeo problemático não
# atrasa mais a migração de nenhuma empresa.
#
# A fila roda POR EMPRESA (não mais uma fila genérica por usuário) e
# gera uma atividade `transcricao_video` própria — mesmo padrão da
# `migracao_midia` (ver criar_atividade/atualizar_atividade mais abaixo):
# assim o sino de notificações mostra "X de Y vídeos transcritos" por
# empresa, com barra de progresso, em vez do badge "⏳ Transcrevendo…"
# no card do vídeo ser a única pista (e uma pista sem nenhuma noção de
# quantidade ou de tempo decorrido — exatamente o problema de "como sei
# que não travou" que motivou essa mudança).

import threading

_lock_transcricao_pendente = threading.Lock()

@st.cache_resource
def _get_transcricoes_empresa_ativas_agora() -> set:
    # @st.cache_resource (não uma variável solta no módulo) porque o
    # Streamlit reexecuta o script inteiro do zero a cada rerun — uma
    # variável de módulo comum voltaria a set() vazio a cada rerun,
    # quebrando a trava "já tem uma fila rodando pra essa empresa" (mesmo
    # motivo pelo qual get_r2_client() e get_whisper_model() já usam esse
    # decorator). cache_resource devolve sempre a MESMA instância do set,
    # compartilhada por todo o processo, sobrevivendo aos reruns.
    return set()

_transcricoes_empresa_ativas_agora = _get_transcricoes_empresa_ativas_agora()  # elementos: (user_id, empresa) — evita 2 filas rodando pra mesma empresa ao mesmo tempo

def _contar_transcricoes_pendentes(user_id: str, empresa: str) -> int:
    """Quantos vídeos dessa empresa já foram migrados (estão em `midias`)
    mas ainda não têm transcrição salva (`transcricao` NULL)."""
    try:
        res = (
            supabase.table("midias")
            .select("id", count="exact")
            .eq("user_id", user_id)
            .eq("empresa", empresa)
            .eq("tipo", "video")
            .is_("transcricao", "null")
            .execute()
        )
        return res.count or 0
    except Exception:
        return 0

def _empresas_com_transcricao_pendente(user_id: str) -> list:
    """Lista as empresas distintas do usuário que ainda têm vídeo migrado
    sem transcrição — usada pelo auto-retry da sidebar (periodicamente) pra
    saber quais filas de transcrição precisam ser (re)ligadas, do mesmo
    jeito que retentar_migracoes_travadas_automaticamente faz pra
    migração."""
    try:
        res = (
            supabase.table("midias")
            .select("empresa")
            .eq("user_id", user_id)
            .eq("tipo", "video")
            .is_("transcricao", "null")
            .limit(2000)
            .execute()
        )
        return sorted({r["empresa"] for r in (res.data or []) if r.get("empresa")})
    except Exception:
        return []

def _transcrever_pendentes_background(user_id: str, empresa: str, atividade_id: str = None):
    """Processa a fila de transcrição de UMA empresa até esvaziar, indo
    atualizando `atividade_id` a cada vídeo terminado — é essa atualização
    ao vivo (via o mesmo st.fragment de 2s que já anima a migração) que
    deixa visível que a transcrição está progredindo de verdade, em vez
    de só um badge estático que não muda nunca.

    BUG CORRIGIDO (visto em produção: atividade de Kedu passou de "8 de
    8" pra "522 de 528" numa hora, com só 30 vídeos de verdade no banco):
    se o UPDATE que grava a transcrição falhasse pra uma linha (RLS,
    rede, sessão do Supabase expirada — client guardado em st.session_state
    tem TTL de token), a linha continuava NULL no banco pra sempre.
    Como a query de busca não excluía nada, a MESMA linha voltava a
    aparecer em toda volta do `while True`, era baixada e transcrita de
    novo, `transcritas` (e `total`, que segue `transcritas`) incrementava
    de novo — um loop infinito silencioso que nunca chegava a
    'concluído' e inflava os números sem limite. A correção: cada linha
    só pode ser tentada UMA VEZ por execução desta thread — sucesso ou
    falha, ela sai da fila desta passada (rastreada em
    `_ids_tentados_neste_run`, excluída da próxima busca via
    `.not_.in_`). Falhas de verdade agora ficam registradas em
    `_ids_falharam` e reportadas na atividade (status 'erro', com
    'aviso' explicando quantas falharam) em vez de desaparecerem."""
    _chave_ativa = (user_id, empresa)
    transcritas = 0
    total = _contar_transcricoes_pendentes(user_id, empresa)
    _ids_tentados_neste_run = set()
    _ids_falharam = []
    # V75 — diagnóstico por mídia. Antes o card só dizia "falha de rede/IA",
    # o que não permitia saber se o problema era download, arquivo inválido,
    # inicialização do EasyOCR, leitura OCR ou gravação no banco.
    _erros_detalhados = []
    _erros_update_amostra = []  # guarda a mensagem real de até 3 falhas, pra diagnosticar a causa (RLS, coluna estourada, etc.) sem precisar de acesso a log de servidor
    try:
        while True:
            try:
                _query = (
                    supabase.table("midias")
                    .select("id, url_cdn")
                    .eq("user_id", user_id)
                    .eq("empresa", empresa)
                    .eq("tipo", "video")
                    .is_("transcricao", "null")
                )
                if _ids_tentados_neste_run:
                    # Exclui linhas já tentadas NESTA execução — sucesso
                    # ou falha, não volta pra fila até a próxima vez que
                    # iniciar_transcricao_pendente_background for chamada
                    # do zero. Sem isso, uma linha cujo UPDATE falha fica
                    # NULL pra sempre e é reprocessada em loop infinito.
                    _query = _query.not_.in_("id", list(_ids_tentados_neste_run))
                res = _query.limit(5).execute()
            except Exception:
                break
            pendentes = res.data or []
            if not pendentes:
                break
            # Pode ter surgido vídeo NOVO pra essa empresa depois que
            # `total` foi calculado lá em cima (ex: outro fluxo de mídia —
            # reprocessamento, retentativa, uma migração concorrente —
            # inseriu mais um vídeo com `transcricao` NULL enquanto essa
            # fila já estava rodando). Sem este recálculo, a barra
            # chegava em "19 de 19" (100%) e ficava ali parada enquanto a
            # thread, na real, seguia processando um 20º vídeo que o
            # total antigo não previa — a atividade continuava
            # 'em_andamento' (correto), mas visualmente parecia travada
            # em 100% em vez de mostrar "19 de 20" e a barra recuando pra
            # 95%. Só recalcula aqui (uma vez por lote de 5, não por
            # vídeo) pra não gerar uma query extra a cada item.
            total_real = transcritas + _contar_transcricoes_pendentes(user_id, empresa)
            if total_real > total:
                total = total_real
                if atividade_id:
                    atualizar_atividade(atividade_id, "em_andamento", {
                        "empresa": empresa,
                        "transcritas": transcritas,
                        "total": total,
                        "ultimo_heartbeat_em": _agora_iso(),
                    })
            for midia in pendentes:
                _ids_tentados_neste_run.add(midia["id"])
                # String vazia (em vez de deixar NULL) marca "já tentei
                # transcrever esse vídeo" — sem isso, um vídeo sem áudio
                # (ou que falha sempre) ficaria sendo pego por essa mesma
                # fila pra sempre, a cada ciclo.
                texto = ""
                try:
                    resp = _http_get(midia["url_cdn"], timeout=30)
                    resp.raise_for_status()
                    texto = _transcrever_video_whisper(resp.content)
                except Exception:
                    pass
                try:
                    supabase.table("midias").update({"transcricao": texto or ""}).eq("id", midia["id"]).execute()
                except Exception as _e_update:
                    # Não faz mais "pass" silencioso: fica registrado (id
                    # já está em _ids_tentados_neste_run, então não volta
                    # a ser tentado nesta execução) e vira um "erro" real
                    # no fim, visível no sino, em vez de sumir sem deixar
                    # rastro. Guarda a mensagem de verdade (até 3
                    # amostras) pra dar pra diagnosticar a causa raiz.
                    _ids_falharam.append(str(midia["id"]))
                    if len(_erros_update_amostra) < 3:
                        _erros_update_amostra.append(f"{midia['id']}: {_e_update}")
                transcritas += 1
                if atividade_id:
                    # Regrava 'empresa' em TODO update de detalhes (mesmo
                    # cuidado de _migrar_midia_background) porque
                    # atualizar_atividade substitui o dict inteiro, não
                    # faz merge — sem isso, esse update apagaria a
                    # empresa dos detalhes e o botão "Refazer" perderia a
                    # referência de qual empresa é essa atividade.
                    atualizar_atividade(atividade_id, "em_andamento", {
                        "empresa": empresa,
                        "transcritas": transcritas,
                        "total": max(total, transcritas),
                        "ultimo_heartbeat_em": _agora_iso(),
                    })
        if atividade_id:
            if _ids_falharam:
                # Pelo menos um UPDATE falhou de verdade — não marca
                # 'concluido' fingindo que deu tudo certo. Fica 'erro',
                # com o botão "Refazer" disponível (que só tenta de novo
                # os que ainda estiverem NULL — os que tiveram sucesso
                # não voltam pra fila).
                atualizar_atividade(atividade_id, "erro", {
                    "empresa": empresa,
                    "transcritas": transcritas,
                    "total": max(total, transcritas),
                    "falhou_em": _agora_iso(),
                    "aviso": (
                        f"{len(_ids_falharam)} de {transcritas} vídeos tiveram erro ao "
                        f"salvar a transcrição no banco (rede instável, sessão expirada "
                        f"ou permissão negada) — não vão se resolver sozinhos nesta "
                        f"passada. Clique 'Refazer' pra tentar de novo, ou aguarde: o "
                        f"religamento automático da sidebar também tenta periodicamente.\n"
                        f"Detalhe técnico (até 3 amostras): {' | '.join(_erros_update_amostra)}"
                    ),
                })
            else:
                atualizar_atividade(atividade_id, "concluido", {
                    "empresa": empresa,
                    "transcritas": transcritas,
                    "total": max(total, transcritas),
                })
    except Exception as e:
        if atividade_id:
            atualizar_atividade(atividade_id, "erro", {
                "empresa": empresa,
                "motivo": str(e),
                "transcritas": transcritas,
                "total": max(total, transcritas),
            })
    finally:
        with _lock_transcricao_pendente:
            _transcricoes_empresa_ativas_agora.discard(_chave_ativa)

def _transcrever_pendentes_na_fila_global(user_id: str, empresa: str, atividade_id: str = None):
    """Executa a fila de transcrição sob a MESMA exclusividade do OCR/migração."""
    _ticket = None
    try:
        _ticket = _entrar_fila_acao_pesada("TRANSCRIÇÃO", empresa)
        if atividade_id:
            atualizar_atividade(atividade_id, "em_andamento", {
                "empresa": empresa,
                "transcritas": 0,
                "total": _contar_transcricoes_pendentes(user_id, empresa),
                "ultimo_heartbeat_em": _agora_iso(),
                "aviso": "Transcrição em processamento.",
            })

        # O modelo Whisper só é carregado DEPOIS que a transcrição ganha a
        # vez na fila. Antes, iniciar_transcricao... carregava o modelo antes
        # da fila e podia criar um pico de RAM enquanto o OCR estava ativo.
        if whisper_model_ou_none() is None:
            if atividade_id:
                atualizar_atividade(atividade_id, "erro", {
                    "empresa": empresa,
                    "motivo": "Whisper indisponível para transcrição.",
                })
            with _lock_transcricao_pendente:
                _transcricoes_empresa_ativas_agora.discard((user_id, empresa))
            return

        _transcrever_pendentes_background(user_id, empresa, atividade_id)
    finally:
        if _ticket is not None:
            _sair_fila_acao_pesada(_ticket)


def iniciar_transcricao_pendente_background(user_id: str, empresa: str):
    """Dispara (se ainda não tiver uma rodando pra essa empresa) o
    processamento, em segundo plano, dos vídeos dessa empresa que já
    foram migrados pro R2 mas ainda não têm transcrição salva. Cria/
    reaproveita uma atividade `transcricao_video` pra essa empresa, do
    mesmo jeito que iniciar_migracao_midia_background faz com
    `migracao_midia`. Retorna na hora — nunca bloqueia quem chamou
    (migração, retry automático, etc.)."""
    if not user_id or not empresa:
        return
    with _lock_transcricao_pendente:
        if (user_id, empresa) in _transcricoes_empresa_ativas_agora:
            return
        _transcricoes_empresa_ativas_agora.add((user_id, empresa))
    total = _contar_transcricoes_pendentes(user_id, empresa)
    if not total:
        # Nada pendente pra essa empresa agora — não cria atividade só
        # pra mostrar "0 de 0", isso só poluiria o sino à toa.
        with _lock_transcricao_pendente:
            _transcricoes_empresa_ativas_agora.discard((user_id, empresa))
        return
    atividade_id = _atividade_transcricao_mais_recente_id(user_id, empresa)
    if atividade_id:
        atualizar_atividade(atividade_id, "na_fila", {
            "empresa": empresa, "transcritas": 0, "total": total,
            "status_visual": "na_fila",
            "aviso": "Aguardando a vez na fila global de processamento.",
        })
    else:
        atividade_id = criar_atividade(
            user_id, "transcricao_video", f"{empresa} · Transcrevendo vídeos de anúncios",
            {
                "empresa": empresa, "transcritas": 0, "total": total,
                "status_visual": "na_fila",
                "aviso": "Aguardando a vez na fila global de processamento.",
            },
            status="na_fila",
        )
    threading.Thread(
        target=_transcrever_pendentes_na_fila_global,
        args=(user_id, empresa, atividade_id),
        daemon=True,
        name=f"transcricao-global-{empresa}",
    ).start()


# ---------------------------------------------------
#  OCR DE IMAGENS DO GOOGLE ADS — o Google Ads Transparency Center não
#  expõe texto do anúncio (headline/descrição) via API pública, nem
#  pros anúncios de formato "Texto" (ver comentário em
#  _normalizar_item_apify, na aba Google Ads): tudo chega como imagem
#  crua. Esta fila roda OCR via Gemini Vision sobre as imagens JÁ
#  MIGRADAS pro R2 (link permanente, nunca expira), pra pelo menos
#  mostrar o texto visível no criativo em vez de deixar o card sem
#  nenhuma copy.
#
#  OCR, migração e transcrição compartilham a MESMA fila global exclusiva.
#  chamada em _migrar_midia_background), pra não segurar os workers de
#  download/upload da migração com uma chamada de IA por imagem.
#
#  REQUER MIGRAÇÃO NO BANCO — as colunas abaixo ainda não existem:
#      ALTER TABLE midias ADD COLUMN ocr_texto text;
#      ALTER TABLE midias ADD COLUMN ocr_estruturado jsonb;
#  (mesma convenção 3-estados da coluna `transcricao`: NULL = ainda não
#  processado, "" (ocr_texto) / NULL (ocr_estruturado) = processado e não
#  achou texto, com texto = pronto)
#
#  `ocr_texto` guarda a versão "achatada" (uma linha por trecho) — usada
#  desta migração, que só têm texto corrido, sem os campos separados.
#  `ocr_estruturado` guarda o JSON com os campos reconhecendo que é um
#  anúncio do Google (titulo, descricao, url_exibida, url_final, cta,
#  sitelinks) — usado pra exibir o texto formatado no card.

_lock_ocr_pendente = threading.Lock()

# ---------------------------------------------------
# EASYOCR — leitor local, sem chamada de API/cota
# ---------------------------------------------------
# Substitui o Gemini como "leitor" da imagem: baixa a imagem e devolve o
# texto bruto que o EasyOCR enxergou nela (sem nenhuma tentativa de
# separar em título/descrição/CTA/url — isso fica pra uma etapa
# seguinte, depois de ver como o texto bruto costuma vir). Roda no
# próprio processo, sem limite de requisições por minuto.
#
# Trocamos o PaddleOCR pelo EasyOCR porque o `paddlepaddle` ainda não
# publica wheel pro Python 3.14 (versão usada no Streamlit Community
# Cloud), o que quebrava o build ("No matching distribution found for
# paddlepaddle"). O EasyOCR depende do PyTorch, que já tem suporte
# oficial ao Python 3.14 desde a versão 2.10.
_lock_easyocr_init = threading.Lock()
_easyocr_instancia = [None]

# Cadência GLOBAL das chamadas ao EasyOCR — cada empresa roda numa thread
# própria (ver iniciar_ocr_pendente_background), então várias empresas
# com OCR pendente ao mesmo tempo podiam disparar várias inferências de
# rede neural em paralelo, somando toda a CPU/RAM do processo de uma vez
# só — foi isso que fez o Streamlit Cloud throttlar o app. Este lock
# serializa as chamadas ao motor (uma imagem por vez, não importa quantas
# threads estejam tentando), e o intervalo mínimo dá um respiro pro
# processo entre uma inferência e outra.
#
# O valor de 1.5s não foi suficiente — o app foi throttlado por uso de
# CPU mesmo assim, porque o intervalo só cobria o "descanso" entre
# chamadas, mas cada chamada em si (download + banda de cor + inferência
# do EasyOCR) já consome CPU por vários segundos, e com filas de várias
# empresas rodando em sequência isso vira uso de CPU quase contínuo.
# Subido pra 6s de respiro mínimo entre uma imagem e a próxima (além do
# tempo que a própria imagem leva pra processar) — mais lento pra
# esvaziar a fila, mas dá ao processo intervalos reais de ociosidade
# entre inferências, que é o que o limitador de CPU do Streamlit Cloud
# está olhando. Se ainda throttlar com esse valor, subir mais.
_lock_easyocr_execucao = threading.Lock()
_MIN_INTERVALO_OCR_SEG = 15.0  # V31: reduz duty-cycle de CPU e risco de throttling
_ultima_chamada_ocr = [0.0]

# O primeiro carregamento do EasyOCR é o ponto de maior pico de memória:
# importa torch, abre os pesos e, se faltarem, baixa o detector. Mantemos
# estado de falha/cooldown para não repetir esse pico em loop após erro.
_easyocr_init_falhou_em = [0.0]
_EASYOCR_INIT_COOLDOWN_SEG = 300.0

def _rss_processo_mb() -> float:
    """RSS real do processo no Linux/Streamlit Cloud."""
    try:
        with open("/proc/self/status", "r", encoding="utf-8") as _f:
            for _linha in _f:
                if _linha.startswith("VmRSS:"):
                    return float(_linha.split()[1]) / 1024.0
    except Exception:
        pass
    return 0.0

def _liberar_memoria_ocr(contexto: str = "") -> float:
    """Limpa objetos Python e tenta devolver heap livre à libc."""
    try:
        gc.collect()
    except Exception:
        pass
    try:
        import ctypes as _ctypes_mem
        _ctypes_mem.CDLL("libc.so.6").malloc_trim(0)
    except Exception:
        pass
    _rss = _rss_processo_mb()
    if contexto:
        print(f"[MEM-DEBUG] {contexto}: RSS={_rss:.1f} MB", flush=True)
    return _rss


def _get_easyocr():
    """Inicializa o EasyOCR uma única vez, de forma serializada e protegida.

    A inicialização também entra no semáforo global de CPU pesada. Antes,
    somente a inferência estava protegida; duas filas podiam chegar juntas
    ao primeiro uso e uma delas ficava esperando enquanto o processo ainda
    carregava PyTorch/modelos. Agora o pico de inicialização não concorre com
    ffmpeg/Whisper e uma falha não dispara novas tentativas por 5 minutos.
    """
    if _easyocr_instancia[0] is not None:
        return _easyocr_instancia[0]

    agora = time.monotonic()
    if _easyocr_init_falhou_em[0] and (agora - _easyocr_init_falhou_em[0]) < _EASYOCR_INIT_COOLDOWN_SEG:
        raise RuntimeError("EasyOCR em cooldown após falha recente de inicialização")

    with _lock_easyocr_init:
        if _easyocr_instancia[0] is not None:
            return _easyocr_instancia[0]
        try:
            with _recurso_cpu_pesada("easyocr-init"):
                # V112 — a trava de memória precisa olhar o RSS ANTES de
                # importar EasyOCR/PyTorch. Na V111 ela era aplicada depois do
                # import e, por isso, contava os ~650 MB normais do próprio
                # PyTorch como se fossem memória ocupada pelo restante do app.
                # Resultado observado: ~293 MB antes do import -> ~960 MB após
                # o import -> bloqueio artificial no limite de 850 MB.
                _rss_antes_easyocr = _liberar_memoria_ocr("antes EasyOCR init")
                _LIMITE_RSS_ANTES_IMPORT_MB = int(
                    st.secrets.get("OCR_MAX_RSS_ANTES_IMPORT_EASYOCR_MB", 650)
                )
                if _rss_antes_easyocr > _LIMITE_RSS_ANTES_IMPORT_MB:
                    raise RuntimeError(
                        f"Memória base alta demais para iniciar EasyOCR com segurança "
                        f"(RSS={_rss_antes_easyocr:.0f} MB antes do import; limite="
                        f"{_LIMITE_RSS_ANTES_IMPORT_MB} MB)"
                    )

                print("[OCR-DEBUG] inicializando EasyOCR (única instância global)...", flush=True)
                import easyocr

                # Só agora torch/cv2 são carregados (como dependências do
                # EasyOCR). O RSS daqui inclui o custo NORMAL do PyTorch e não
                # deve ser usado como trava preventiva antes do Reader.
                _limitar_threads_cpu_ocr_apos_import()
                _liberar_memoria_ocr("apos import EasyOCR/torch, antes Reader")

                _easyocr_instancia[0] = easyocr.Reader(
                    ["pt"], gpu=False, verbose=False
                )
                _liberar_memoria_ocr("depois EasyOCR init")
                print("[OCR-DEBUG] EasyOCR inicializado com sucesso", flush=True)
        except BaseException:
            _easyocr_init_falhou_em[0] = time.monotonic()
            gc.collect()
            raise
    return _easyocr_instancia[0]

def _baixar_imagem_cv2(url_imagem: str):
    """Baixa a imagem (já no nosso R2) e devolve o array BGR decodificado
    (formato que o OpenCV/EasyOCR esperam), ou None se o download ou a
    decodificação falharem."""
    import numpy as _np_ocr
    import cv2 as _cv2_ocr
    r = _http_get(url_imagem, timeout=20)
    r.raise_for_status()
    _arr = _np_ocr.frombuffer(r.content, dtype=_np_ocr.uint8)
    _img = _cv2_ocr.imdecode(_arr, _cv2_ocr.IMREAD_COLOR)
    if _img is None:
        return None
    # Evita que screenshots anormalmente gigantes façam o EasyOCR reservar
    # dezenas/centenas de MB só para tensores intermediários. Criativos
    # normais ficam intocados; apenas imagens acima de 2200 px no maior lado
    # são reduzidas proporcionalmente.
    _h, _w = _img.shape[:2]
    _maior = max(_h, _w)
    if _maior > 2200:
        _escala = 2200.0 / float(_maior)
        _img = _cv2_ocr.resize(
            _img, (max(1, int(_w * _escala)), max(1, int(_h * _escala))),
            interpolation=_cv2_ocr.INTER_AREA,
        )
    return _img

def _ocr_texto_bruto(img_bgr, reader) -> str:
    """Lê TODO o texto da imagem sem nenhuma tentativa de estruturar —
    usado como fallback quando `_estruturar_anuncio_google_ads` não
    reconhece o padrão de cores esperado (ex: anúncio de imagem/Display,
    em vez de anúncio de texto).

    width_ths baixo (padrão do EasyOCR é 0.5) evita que o CRAFT funda
    palavras próximas numa ÚNICA caixa de detecção — quando isso
    acontece, o reconhecedor devolve as palavras GRUDADAS, sem espaço
    entre elas (ex: título de anúncio virando "ReduzirInadimplência
    Escolar"), porque o modelo de reconhecimento não emite espaço de
    forma confiável em recortes largos com várias palavras. Com caixas
    menores (uma por palavra), a reconstrução manual de espaço vira
    desnecessária pro fallback, mas o texto pelo menos não sai
    concatenado.

    Ordena por posição (linha de cima pra baixo, esquerda pra direita
    dentro de cada linha) antes de juntar — sem isso, a ordem das
    palavras é a ordem em que o CRAFT detectou cada região, que não
    tem nenhuma relação com a ordem de leitura (validado num anúncio
    real: o texto saiu com pedaços do título, da descrição e de um
    sitelink todos embaralhados entre si)."""
    resultado = reader.readtext(img_bgr, detail=1, width_ths=0.15, height_ths=0.5)
    if not resultado:
        return ""
    # Agrupa por linha (centro Y de cada caixa) antes de ordenar por X
    # — do contrário, duas palavras de linhas DIFERENTES mas X parecido
    # (comum quando uma linha começa mais à esquerda que a de cima)
    # ficam vizinhas na ordenação e saem misturadas.
    _itens = [(bbox, (t or "").strip()) for bbox, t, _conf in resultado if (t or "").strip()]
    if not _itens:
        return ""
    def _y_centro(bbox):
        return sum(p[1] for p in bbox) / len(bbox)
    _itens.sort(key=lambda item: _y_centro(item[0]))
    _linhas_agrupadas = []
    _linha_atual = [_itens[0]]
    _y_ref = _y_centro(_itens[0][0])
    _altura_media = max(1.0, sum(max(p[1] for p in it[0]) - min(p[1] for p in it[0]) for it in _itens) / len(_itens))
    for item in _itens[1:]:
        _y_item = _y_centro(item[0])
        if abs(_y_item - _y_ref) > _altura_media * 0.6:
            _linhas_agrupadas.append(_linha_atual)
            _linha_atual = [item]
        else:
            _linha_atual.append(item)
        _y_ref = _y_item
    _linhas_agrupadas.append(_linha_atual)
    linhas = []
    for _grupo in _linhas_agrupadas:
        _grupo.sort(key=lambda item: item[0][0][0])
        linhas.append(" ".join(t for _bbox, t in _grupo))
    return "\n".join(linhas)

_REGEX_PATROCINADO = re.compile(r"^(patrocinad[oa]|sponsored|gesponsord|gesponsert|sponsoris[ée])$", re.IGNORECASE)
# o caso em que "Patrocinado" cai grudado, na MESMA banda de cor, com
# a linha seguinte (nome da página/anunciante) — gap vertical pequeno
# demais pra `_detectar_bandas_texto` separar em duas bandas — saindo
# do OCR como "Patrocinado BuyTicket Brasil" ou "PatrocinadoBuyTicket
# Brasil" em vez de duas linhas isoladas. Nesse caso o match EXATO
# acima (`_REGEX_PATROCINADO`) falha, e sem esse segundo padrão a
# banda inteira sobrevivia intacta como se fosse cabeçalho — grudando
# a palavra "Patrocinado" na frente do nome da página/URL (validado
# num anúncio real da BuyTicket Brasil, ver print reportado pelo
# usuário). `[\s:\-]*` absorve o espaço/pontuação residual que
# costuma sobrar entre o rótulo e o texto seguinte.
_REGEX_PATROCINADO_PREFIXO = re.compile(r"^(patrocinad[oa]|sponsored|gesponsord|gesponsert|sponsoris[ée])", re.IGNORECASE)
# Formato de domínio/URL: precisa ter pelo menos um "." separando
# letras/números (ex: "kedu.com.br", "www.kedu.com.br/"). Usado pra
# distinguir, dentro do cabeçalho (tudo antes do primeiro azul), a
# linha que É a URL exibida das linhas que NÃO são (ex: nome da
# página/anunciante ao lado do favicon, tipo "KEDU") — essas não têm
# ponto e não devem ser misturadas no url_exibida.
_REGEX_FORMATO_DOMINIO = re.compile(r"^[a-z0-9\-]+(\.[a-z0-9\-]+)+(/\S*)?$", re.IGNORECASE)
# CTA final do anúncio (ex: botão "Enviar mensagem" do WhatsApp, "Ligar
# um separador, com um ícone colorido à esquerda (ignorado na
# classificação de cor — ver `_detectar_bandas_texto`) seguido de um
# título curto e, na maioria das vezes, um subtítulo cinza logo abaixo
# (ex: "pelo app WhatsApp"). Como o ícone fica fora da faixa usada pra
# cor, essa banda chega classificada como "cinza" (não "misto"), e sem
# esse reconhecimento por texto ela era só mais uma linha de descrição
# grudada no sitelink anterior. Lista inicial validada com anúncios
# reais da kedu — dá pra ir completando conforme aparecerem outros CTAs.
# V91 — inclui também a forma imperativa real do Google Ads em PT-BR: "Compre Agora".
# A lista anterior só reconhecia "Comprar Agora", então o look-ahead da V90 não
# identificava o CTA final e deixava o texto promocional interno da arte ocupar o CTA.
_REGEX_CTA_TITULO_CONHECIDO = re.compile(
    r"^(enviar\s*mensagem|ligar\s*agora|comprar\s*agora|compre\s*agora|saiba\s*mais|"
    r"cadastre-?se|fazer\s*pedido|agendar(\s*agora)?|reservar(\s*agora)?|"
    r"inscreva-?se|baixar\s*agora|instalar(\s*agora)?|pe(ç|c)a\s*já|"
    # "entre em contato" aceita um complemento CURTO e ESPECÍFICO colado
    # na mesma linha ("no app WhatsApp") — validado em anúncio real da
    # isaac, onde o CTA e esse complemento saem juntos numa banda só do
    # OCR. Restrito a essa continuação exata (não texto livre) porque
    # uma versão anterior aceitava QUALQUER texto depois de qualquer
    # gatilho da lista — e "saiba mais" também é um gatilho aqui, só
    # que "saiba mais" é comum aparecer no MEIO de uma descrição normal
    # (ex: "Saiba Mais Descubra como o Isaac pode ajudar..."), então
    # aceitar texto livre depois dele fazia o meio da descrição virar
    # CTA por engano, cortando o parágrafo ao meio.
    r"entre\s*em\s*contato(\s+no\s*app\s*whatsapp)?|fale\s*conosco|fale\s*com\s*a\s*gente)$",
    re.IGNORECASE,
)

# ---------------------------------------------------
#  ÍCONES SVG — CTA FINAL DO ANÚNCIO DO GOOGLE ADS (ex: círculo verde do
#  WhatsApp ao lado de "Enviar mensagem"). O ícone real fica fora da
#  faixa usada por `_detectar_bandas_texto` pra classificar a cor da
#  banda (ver comentário lá), então não dá pra recuperar a cor exata do
#  pixel — a escolha do ícone/cor abaixo é por palavra-chave no texto do
#  CTA e no subtítulo (ex: "pelo app WhatsApp"), reproduzindo visualmente
#  o círculo colorido que a Central de Transparência mostra de verdade,
#  em vez de deixar o CTA como só mais uma linha de texto sem ícone.
# ---------------------------------------------------

