def _atividade_migracao_aberta_id(user_id: str, empresa: str, plataforma: str = None):
    """Acha o id de uma atividade migracao_midia ainda aberta (pendente/
    em_andamento) pra essa empresa específica, se existir. Devolve None
    se não tem nenhuma. Serve de base tanto pra migracao_midia_em_
    andamento() (só quer saber se existe uma rodando agora) quanto pra
    quem precisa saber especificamente se há algo em aberto.

    `plataforma` ("Meta Ads"/"Google Ads") filtra pra não misturar a
    migração de uma empresa que existe nas DUAS fontes (nome igual em
    Meta Ads e Google Ads) numa única atividade — sem isso, a barra de
    progresso de uma acabava "emprestada" pra outra. Registros antigos
    (de antes dessa distinção existir) não têm essa chave nos detalhes;
    são tratados como "Meta Ads" (é a plataforma original do app, e é
    de onde vieram todos os registros anteriores a essa mudança)."""
    if not user_id:
        return None
    try:
        res = (
            supabase.table("atividades")
            .select("id, detalhes")
            .eq("user_id", user_id)
            .eq("tipo", "migracao_midia")
            .in_("status", ["pendente", "na_fila", "em_andamento"])
            .order("criado_em", desc=True)
            .execute()
        )
        for a in (res.data or []):
            _d = a.get("detalhes") or {}
            if _d.get("empresa") != empresa:
                continue
            if plataforma and _d.get("plataforma", "Meta Ads") != plataforma:
                continue
            return a["id"]
        return None
    except Exception:
        return None

def _atividade_migracao_mais_recente_id(user_id: str, empresa: str, plataforma: str = None):
    """Acha a atividade migracao_midia mais recente dessa empresa,
    NÃO importa o status (concluído, erro, em andamento...). Usada na
    hora de decidir se cria uma atividade nova ou se reaproveita uma
    existente: reaproveitar mesmo uma já 'concluída' evita duplicar o
    card quando a mesma empresa volta a ter pendência depois (nova
    coleta trazendo anúncios novos, ou uma varredura achando itens
    antigos que na época não estavam ali) — antes, só reaproveitava
    atividades em 'pendente'/'em_andamento', então qualquer empresa que
    já tivesse fechado como 'concluído' uma vez ganhava um card NOVO na
    próxima vez que precisasse migrar mais alguma coisa, em vez de só
    'empurrar' a mesma pra frente de novo.

    `plataforma`: mesmo motivo do parâmetro em _atividade_migracao_
    aberta_id — sem isso, uma empresa com o mesmo nome em Meta Ads e
    Google Ads compartilhava a mesma atividade/card de migração entre
    as duas plataformas."""
    if not user_id:
        return None
    try:
        res = (
            supabase.table("atividades")
            .select("id, detalhes")
            .eq("user_id", user_id)
            .eq("tipo", "migracao_midia")
            .order("criado_em", desc=True)
            .limit(50)
            .execute()
        )
        for a in (res.data or []):
            _d = a.get("detalhes") or {}
            if _d.get("empresa") != empresa:
                continue
            if plataforma and _d.get("plataforma", "Meta Ads") != plataforma:
                continue
            return a["id"]
        return None
    except Exception:
        return None

def migracao_midia_em_andamento(user_id: str, empresa: str) -> bool:
    """Confere se ainda existe uma migração de mídia (download+compressão+
    transcrição) rodando em background pra essa empresa específica —
    usado pra avisar o usuário que uma análise de IA feita agora pode não
    pegar todos os vídeos ainda (alguns podem não ter transcrição pronta
    até a migração terminar)."""
    return _atividade_migracao_aberta_id(user_id, empresa) is not None

def _atividade_transcricao_aberta_id(user_id: str, empresa: str):
    """Igual a _atividade_migracao_aberta_id, mas pra atividades
    `transcricao_video`: acha o id de uma atividade ainda aberta
    (pendente/em_andamento) dessa empresa, se existir."""
    if not user_id:
        return None
    try:
        res = (
            supabase.table("atividades")
            .select("id, detalhes")
            .eq("user_id", user_id)
            .eq("tipo", "transcricao_video")
            .in_("status", ["pendente", "na_fila", "em_andamento"])
            .order("criado_em", desc=True)
            .execute()
        )
        for a in (res.data or []):
            if (a.get("detalhes") or {}).get("empresa") == empresa:
                return a["id"]
        return None
    except Exception:
        return None

def _atividade_transcricao_mais_recente_id(user_id: str, empresa: str):
    """Igual a _atividade_migracao_mais_recente_id, mas pra
    `transcricao_video`: acha a atividade mais recente dessa empresa não
    importa o status, pra reaproveitar o mesmo card em vez de duplicar
    (mesmo motivo: uma empresa pode voltar a ter vídeo pendente de
    transcrição depois de uma atividade anterior já ter fechado como
    'concluído' — nova migração trazendo vídeos novos, por exemplo)."""
    if not user_id:
        return None
    try:
        res = (
            supabase.table("atividades")
            .select("id, detalhes")
            .eq("user_id", user_id)
            .eq("tipo", "transcricao_video")
            .order("criado_em", desc=True)
            .limit(50)
            .execute()
        )
        for a in (res.data or []):
            if (a.get("detalhes") or {}).get("empresa") == empresa:
                return a["id"]
        return None
    except Exception:
        return None

def _atividade_ocr_mais_recente_id(user_id: str, empresa: str):
    """Igual a _atividade_migracao_mais_recente_id/_atividade_transcricao_
    mais_recente_id, mas pra `ocr_gads`: acha a atividade mais recente
    dessa empresa, não importa o status. Usada em iniciar_ocr_pendente_
    background pra reaproveitar o mesmo card em vez de criar um NOVO
    toda vez que a função é chamada — sem isso, cada chamada (verificação
    de segurança, botão manual, reset de OCR antiga) criava uma
    atividade nova pra mesma empresa, enchendo o sino de cards
    duplicados "Kedu · Extraindo texto..." repetidos."""
    if not user_id:
        return None
    try:
        res = (
            supabase.table("atividades")
            .select("id, detalhes")
            .eq("user_id", user_id)
            .eq("tipo", "ocr_gads")
            .order("criado_em", desc=True)
            .limit(50)
            .execute()
        )
        for a in (res.data or []):
            if (a.get("detalhes") or {}).get("empresa") == empresa:
                return a["id"]
        return None
    except Exception:
        return None

def transcricao_video_em_andamento(user_id: str, empresa: str) -> bool:
    """Confere se ainda existe uma fila de transcrição rodando em
    background pra essa empresa específica — mesmo uso de
    migracao_midia_em_andamento, mas pro Whisper."""
    return _atividade_transcricao_aberta_id(user_id, empresa) is not None

def _agora_iso() -> str:
    """ISO 8601 em UTC — usado pra carimbar quando uma atividade foi
    tocada por último, sem depender de coluna própria no banco."""
    import datetime as _dt
    return _dt.datetime.now(_dt.timezone.utc).isoformat()

def _segundos_desde(iso_str: str) -> float:
    """Quantos segundos se passaram desde um timestamp ISO salvo em
    `detalhes`. Devolve infinito se o timestamp não existir ou não der
    pra ler — assim, atividades antigas (de antes desse campo existir)
    contam como "muito paradas" em vez de nunca serem retentadas."""
    if not iso_str:
        return float("inf")
    try:
        import datetime as _dt
        dt = _dt.datetime.fromisoformat(iso_str.replace("Z", "+00:00"))
        agora = _dt.datetime.now(_dt.timezone.utc)
        return (agora - dt).total_seconds()
    except Exception:
        return float("inf")

import re as _re_ativ

def _extrair_empresa_do_titulo_migracao(titulo: str):
    """Fallback pra recuperar o nome da empresa quando `detalhes.empresa`
    não está presente numa atividade migracao_midia — o que já aconteceu
    com registros antigos porque atualizar_atividade() substitui o dict
    de detalhes inteiro (não faz merge), então uma atualização de
    progresso sem a chave 'empresa' apagava esse dado do registro,
    mesmo com a atividade ainda bem identificada pelo título. O título é
    montado sempre no mesmo formato em iniciar_migracao_midia_background
    ('{empresa} · Salvando anúncios do {plataforma} na Biblioteca de
    Arquivos Permanente' — formato atual, com a plataforma; formatos
    anteriores, sem a plataforma ('{empresa} · Salvando anúncios na
    Biblioteca de Arquivos Permanente') ou ainda mais antigos
    ('Salvando anúncios de {empresa} na Biblioteca de Arquivos
    Permanente'), também são tentados), então dá pra extrair de volta
    com segurança. Sem esse fallback, uma atividade antiga fica com o
    botão de continuar escondido pra sempre (só se resolveria na
    próxima vez que algo regravasse os detalhes) — com ele, a tela se
    autocorrige na hora, sem precisar esperar nenhuma nova escrita no
    banco."""
    if not titulo:
        return None
    m = _re_ativ.match(r"^(.+) · Salvando anúncios do (?:Meta Ads|Google Ads) na Biblioteca de Arquivos Permanente$", titulo)
    if m:
        return m.group(1)
    m = _re_ativ.match(r"^(.+) · Salvando anúncios na Biblioteca de Arquivos Permanente$", titulo)
    if m:
        return m.group(1)
    m = _re_ativ.match(r"^Salvando anúncios de (.+) na Biblioteca de Arquivos Permanente$", titulo)
    return m.group(1) if m else None

def _tempo_relativo(iso_str: str) -> str:
    try:
        import datetime as _dt
        dt = _dt.datetime.fromisoformat(iso_str.replace("Z", "+00:00"))
        agora = _dt.datetime.now(_dt.timezone.utc)
        delta = agora - dt
        seg = delta.total_seconds()
        if seg < 60:
            return "agora mesmo"
        if seg < 3600:
            return f"há {int(seg // 60)} min"
        if seg < 86400:
            return f"há {int(seg // 3600)} h"
        return f"há {int(seg // 86400)} d"
    except Exception:
        return ""

_PARES_PROGRESSO_POR_TIPO = {
    # tipo: (chave_feitos, chave_total) — usado só pra desenhar a barra
    # de progresso com %; cobre os tipos cujos detalhes trazem uma
    # contagem "x de y" pareada.
    "migracao_midia":        ("migradas", "total"),
    "transcricao_video":     ("transcritas", "total"),
    "cc_youtube":             ("verificados", "total"),
    "reprocessamento_midia": ("processadas", "total"),
    "reconciliacao_midia":   ("corrigidos", "verificados"),
    "retentativa_midia":     ("recuperadas", "verificadas"),
    "ocr_gads":              ("processadas", "total"),
    # "coleta_ads" NÃO entra aqui: em vez de uma barra agregada única,
    # esse tipo ganhou uma barra POR EMPRESA (ver 'por_empresa' nos
    # detalhes, gravado por _executar_busca_background, e o bloco de
    # renderização "_notif_empresa_html" na página de notificações) —
    # faz mais sentido pro usuário ver o andamento de cada empresa da
    # coleta individualmente do que um único "X de Y" agregado.
}

def _progresso_atividade(atividade: dict):
    """Devolve (feitos, total) pra desenhar a barra de progresso, ou
    None quando essa atividade não tem uma contagem pareada nos
    detalhes (ex: erro sem dados, ou tipo sem noção de progresso)."""
    d = atividade.get("detalhes") or {}
    par = _PARES_PROGRESSO_POR_TIPO.get(atividade.get("tipo", ""))
    if not par:
        return None
    chave_feitos, chave_total = par
    total = d.get(chave_total)
    if chave_feitos not in d or not total:
        return None
    return (d[chave_feitos], total)

def _formatar_detalhes_atividade(atividade: dict):
    """Traduz o campo `detalhes` (livre, varia por tipo de atividade) em
    um ícone + uma linha de texto legível pra mostrar no sino/página de
    notificações. Sem isso, informações como 'quantos itens falharam' ou
    'quanto espaço foi economizado' ficam presas no banco, invisíveis
    pro usuário.

    Retorna (icone_svg_html, texto) — o texto vem sem prefixo de emoji
    porque quem renderiza escapa esse texto (segurança contra HTML/JS
    vindo do banco); o ícone já é SVG seguro (paths fixos) e é inserido
    separadamente, sem passar pelo escape. O ícone usa fill="currentColor"
    de propósito — ele deve ter a mesma cor do texto ao lado (herdada do
    elemento pai), não uma cor semântica própria."""
    d = atividade.get("detalhes") or {}
    tipo = atividade.get("tipo", "")

    if d.get("aviso"):
        path, _cor = _ICONE_AVISO
        texto = d["aviso"]
        # Deixa explícito se essa migração pendente está rodando agora (uma
        # thread ativa processando) ou parada esperando a próxima tentativa
        # automática — sem isso, "X de Y salvos, Z pendentes" fica ambíguo:
        # o usuário não sabe se precisa esperar ou se travou de vez.
        if tipo == "migracao_midia" and atividade.get("status") == "em_andamento":
            if _migracao_travada(atividade):
                texto += " · Parado no momento — vamos retomar automaticamente em instantes."
            else:
                texto += " · Rodando agora."
        return _svg_icone(path, "currentColor", 14), texto
    if d.get("motivo"):
        path, _cor = _ICONE_INFO
        return _svg_icone(path, "currentColor", 14), d["motivo"]

    if tipo == "reconciliacao_midia" and ("verificados" in d or "corrigidos" in d):
        path, _cor, _ = _TIPO_ATIVIDADE_LABELS["reconciliacao_midia"]
        texto = f"{d.get('corrigidos', 0)} de {d.get('verificados', 0)} anúncios reconectados na Biblioteca de Arquivos Permanente."
        return _svg_icone(path, "currentColor", 14), texto

    if tipo == "reparo_links" and "verificados" in d:
        path, _cor, _ = _TIPO_ATIVIDADE_LABELS["reparo_links"]
        if d.get("quebrados"):
            texto = f"{d['quebrados']} de {d['verificados']} links quebrados encontrados e enviados pra nova tentativa."
        else:
            texto = f"{d['verificados']} links verificados — nenhum quebrado."
        return _svg_icone(path, "currentColor", 14), texto

    if tipo == "reprocessamento_midia" and "processadas" in d:
        economia = d.get("economizado_mb", 0)
        path, _cor, _ = _TIPO_ATIVIDADE_LABELS["reprocessamento_midia"]
        texto = f"{d.get('processadas', 0)} de {d.get('total', 0)} anúncios otimizados — {economia}MB economizados."
        return _svg_icone(path, "currentColor", 14), texto

    if tipo == "ocr_gads" and "processadas" in d:
        path, _cor, _ = _TIPO_ATIVIDADE_LABELS["ocr_gads"]
        texto = f"{d.get('processadas', 0)} de {d.get('total', 0)} imagens processadas."
        return _svg_icone(path, "currentColor", 14), texto

    if tipo in ("coleta_ads", "coleta_ads_google") and ("coletadas" in d or "com_erro" in d):
        erros_d = d.get("com_erro") or {}
        coletadas_d = d.get("coletadas", [])
        # Enquanto está "em_andamento", mostra progresso de verdade (quantas
        # empresas já foram processadas de quantas no total) em vez de só
        # aparecer algo depois que TODAS terminassem — antes disso o card
        # ficava com o rótulo genérico "Coleta de anúncios" a coleta
        # inteira, sem nenhum sinal de avanço mesmo com várias empresas na
        # fila (ver _executar_busca_background, que agora atualiza a
        # atividade a cada empresa processada).
        if atividade.get("status") == "em_andamento":
            total_d = d.get("total") or len(d.get("empresas") or [])
            concluidas_d = d.get("concluidas", len(coletadas_d) + len(erros_d))
            texto = f"{concluidas_d} de {total_d} empresas processadas"
            if coletadas_d:
                texto += f" — coletadas: {', '.join(coletadas_d)}"
            if erros_d:
                texto += f" — com erro: {', '.join(erros_d.keys())}"
            texto += ". · Rodando agora."
            path, _cor = _ICONE_INFO
            return _svg_icone(path, "currentColor", 14), texto
        texto = f"Coletadas: {', '.join(coletadas_d) or '—'}."
        if erros_d:
            texto += f" Com erro: {', '.join(erros_d.keys())}."
            path, _cor = _ICONE_AVISO
        else:
            path, _cor = _ICONE_OK
        return _svg_icone(path, "currentColor", 14), texto

    if tipo == "coleta_redes" and ("coletados" in d or "com_erro" in d):
        erros_d = d.get("com_erro") or {}
        nomes_ok = d.get("coletados", [])
        # Mesmo padrão do coleta_ads: enquanto está "em_andamento", mostra
        # quantos perfis já foram processados de quantos no total, em vez
        # de só aparecer algo quando TODOS já tivessem terminado (ver
        # _coletar_redes_background, que agora atualiza a atividade a
        # cada perfil processado).
        if atividade.get("status") == "em_andamento":
            total_d = d.get("total") or len(d.get("empresas") or [])
            concluidas_d = d.get("concluidas", len(nomes_ok) + len(erros_d))
            texto = f"{concluidas_d} de {total_d} perfis processados"
            if nomes_ok:
                texto += f" — coletados: {', '.join(nomes_ok)}"
            if erros_d:
                texto += f" — com erro: {', '.join(erros_d.keys())}"
            texto += ". · Rodando agora."
            path, _cor = _ICONE_INFO
            return _svg_icone(path, "currentColor", 14), texto
        total_posts = d.get("total_posts", 0)
        texto = f"Coletados: {', '.join(nomes_ok) or '—'} — {total_posts} posts no total."
        # Info de "posts novos" (antes era uma notificação própria, "X novos
        # posts detectados", que aparecia logo acima desta — redundante,
        # já que as duas eram sobre a mesma coleta). Agora entra como
        # primeira frase deste mesmo card, quando aplicável.
        _por_empresa_nv = d.get("por_empresa_novos") or {}
        if _por_empresa_nv:
            _partes_nv = [f"{_nome_nv} ({_qtd_nv})" for _nome_nv, _qtd_nv in _por_empresa_nv.items()]
            texto = f"Novos posts: {', '.join(_partes_nv)}. " + texto
        if erros_d:
            _detalhes_erro_redes = "; ".join(f"{_nome_e}: {_msg_e}" for _nome_e, _msg_e in erros_d.items())
            texto += f" Com erro: {_detalhes_erro_redes}."
            path, _cor = _ICONE_AVISO
        else:
            path, _cor = _ICONE_OK
        return _svg_icone(path, "currentColor", 14), texto

    if tipo == "migracao_midia" and "migradas" in d:
        path, _cor = _ICONE_OK
        texto = f"{d['migradas']} de {d.get('total', d['migradas'])} anúncios salvos na Biblioteca de Arquivos Permanente."
        return _svg_icone(path, "currentColor", 14), texto

    if tipo == "transcricao_video" and "transcritas" in d:
        total_t = d.get("total", d["transcritas"])
        concluida = atividade.get("status") == "concluido" or d["transcritas"] >= total_t
        path, _cor = _ICONE_OK if concluida else _ICONE_INFO
        texto = f"{d['transcritas']} de {total_t} vídeos de anúncios transcritos."
        if atividade.get("status") == "em_andamento":
            texto += " · Rodando agora."
        return _svg_icone(path, "currentColor", 14), texto

    if tipo == "cc_youtube":
        _total_cc = int(d.get("total") or 0)
        _verif_cc = int(d.get("verificados") or 0)
        _salvos_cc = int(d.get("salvos") or 0)
        _pend_cc = int(d.get("pendentes") or 0)
        if atividade.get("status") == "erro":
            path, _cor = _ICONE_AVISO
            texto = "A verificação de CC dos vídeos do Google Ads falhou e será tentada novamente automaticamente."
            if d.get("motivo"):
                texto += f" Motivo: {d.get('motivo')}."
            return _svg_icone(path, "currentColor", 14), texto
        if atividade.get("status") == "em_andamento":
            path, _cor = _ICONE_INFO
            _emp_cc = d.get("empresa")
            if _emp_cc:
                _lote_cc = d.get("lote_empresa")
                _tot_emp_cc = d.get("total_empresas")
                texto = (
                    f"Verificando CC — {_emp_cc}: {_total_cc} vídeo(s)"
                    + (f" · empresa {_lote_cc}/{_tot_emp_cc}" if _lote_cc and _tot_emp_cc else "")
                    + " · Rodando agora."
                )
            else:
                texto = f"Verificando CC em {_total_cc} vídeo(s) do Google Ads. · Rodando agora."
            return _svg_icone(path, "currentColor", 14), texto
        path, _cor = _ICONE_OK if _pend_cc == 0 else _ICONE_INFO
        if _total_cc == 0:
            texto = d.get("mensagem") or "Nenhum vídeo do Google Ads está pendente de CC."
        else:
            texto = (
                f"{_verif_cc} vídeo(s) verificado(s): {_salvos_cc} CC novo(s) salvo(s) "
                f"e {_pend_cc} vídeo(s) ainda sem CC disponível."
            )
        return _svg_icone(path, "currentColor", 14), texto

    if tipo == "transcricao_reel" and "transcritas" in d:
        total_t = d.get("total", d["transcritas"])
        concluida = atividade.get("status") == "concluido" or d["transcritas"] >= total_t
        _falhas_t = d.get("falhas", 0)
        path, _cor = (_ICONE_AVISO if (concluida and _falhas_t) else _ICONE_OK) if concluida else _ICONE_INFO
        texto = f"{d['transcritas']} de {total_t} Reels transcritos"
        _por_empresa_t = d.get("por_empresa") or {}
        if _por_empresa_t:
            _partes_t = [f"{_nome_t} ({_qtd_t})" for _nome_t, _qtd_t in _por_empresa_t.items()]
            texto += f" — {', '.join(_partes_t)}"
        texto += "."
        if _falhas_t:
            _falhas_emp_t = d.get("falhas_por_empresa") or {}
            if _falhas_emp_t:
                _partes_falha_t = [f"{_nome_f} ({_qtd_f})" for _nome_f, _qtd_f in _falhas_emp_t.items()]
                texto += f" {_falhas_t} não puderam ser transcritos — {', '.join(_partes_falha_t)} (áudio indisponível ou erro no download)."
            else:
                texto += f" {_falhas_t} não puderam ser transcritos (áudio indisponível ou erro no download)."
        if atividade.get("status") == "em_andamento":
            texto += " · Rodando agora."
        return _svg_icone(path, "currentColor", 14), texto

    if tipo == "novos_posts" and "por_empresa" in d:
        path, _cor = _ICONE_OK
        partes_empresa = [
            f"{nome_e} ({qtd_e})" for nome_e, qtd_e in d["por_empresa"].items()
        ]
        texto = f"Novos posts: {', '.join(partes_empresa)}."
        return _svg_icone(path, "currentColor", 14), texto

    # migracao_midia, retentativa_midia, analise_ia sem aviso/motivo) —
    # mostra ao menos o label genérico do tipo, pra sempre ter algo pra
    # ver por trás da setinha em vez de deixar a atividade sem detalhe.
    if tipo in _TIPO_ATIVIDADE_LABELS:
        path, _cor, texto = _TIPO_ATIVIDADE_LABELS[tipo]
        return _svg_icone(path, "currentColor", 14), texto

    return "", ""


# ---------------------------------------------------
#  COOLDOWN + COTA MENSAL (anti-abuso + controle de custo)
# ---------------------------------------------------
# Reaproveita a tabela `atividades`: cada coleta/análise já grava uma
# linha com tipo + criado_em, então usamos isso tanto pra cooldown
# (olhar a última execução desse tipo) quanto pra cota mensal (contar
# quantas rodaram esse mês) — sem precisar de tabela nova.

PLANOS_COOLDOWN_SEGUNDOS = {
    "free":    300,   # 5 min entre cliques na mesma ação
    "starter": 120,   # 2 min
    "pro":     30,    # 30 s
    "agencia": 0,     # sem cooldown
}

# limite de execuções por mês, por tipo de ação. None = ilimitado.
PLANOS_COTA_MENSAL = {
    "coleta_ads":   {"free": 5,  "starter": 30, "pro": 150, "agencia": None},
    "coleta_redes": {"free": 5,  "starter": 30, "pro": 150, "agencia": None},
    "analise_ia":   {"free": 5,  "starter": 40, "pro": 200, "agencia": None},
}

def _ultima_execucao_acao(user_id: str, tipo_acao: str):
    try:
        res = (
            supabase.table("atividades")
            .select("criado_em")
            .eq("user_id", user_id)
            .eq("tipo", tipo_acao)
            .order("criado_em", desc=True)
            .limit(1)
            .execute()
        )
        return res.data[0]["criado_em"] if res.data else None
    except Exception:
        return None

def _contar_execucoes_mes(user_id: str, tipo_acao: str) -> int:
    """Lê o contador já pronto em `uso_organizacao` (O(1), incrementado
    atomicamente por registrar_execucao_acao) em vez de fazer COUNT(*)
    ao vivo em `atividades` toda vez — mais rápido à medida que o
    histórico de atividades cresce."""
    try:
        import datetime as _dt
        mes_atual = _dt.datetime.now().replace(day=1).date().isoformat()
        res = (
            supabase.table("uso_organizacao")
            .select("quantidade")
            .eq("user_id", user_id)
            .eq("tipo_acao", tipo_acao)
            .eq("mes", mes_atual)
            .execute()
        )
        if res.data:
            return res.data[0].get("quantidade", 0)
        return 0
    except Exception:
        # se a tabela/RPC ainda não existir (migração não rodada), cai
        # pro comportamento antigo — nunca bloqueia por causa disso.
        try:
            import datetime as _dt
            inicio_mes = _dt.datetime.now().replace(
                day=1, hour=0, minute=0, second=0, microsecond=0
            ).isoformat()
            res = (
                supabase.table("atividades")
                .select("id", count="exact")
                .eq("user_id", user_id)
                .eq("tipo", tipo_acao)
                .gte("criado_em", inicio_mes)
                .execute()
            )
            return res.count or 0
        except Exception:
            return 0

def verificar_pode_executar_acao(user_id: str, tipo_acao: str):
    """Confere cooldown (anti-abuso) e cota mensal (custo) antes de deixar
    uma coleta/análise rodar. Devolve (permitido: bool, motivo: str)."""
    if not user_id:
        return True, ""
    plano = obter_plano_usuario()

    cooldown_seg = PLANOS_COOLDOWN_SEGUNDOS.get(plano, 300)
    if cooldown_seg > 0:
        ultima = _ultima_execucao_acao(user_id, tipo_acao)
        if ultima:
            try:
                import datetime as _dt
                dt_ultima = _dt.datetime.fromisoformat(ultima.replace("Z", "+00:00"))
                passados = (_dt.datetime.now(_dt.timezone.utc) - dt_ultima).total_seconds()
                if passados < cooldown_seg:
                    return False, f"Aguarde {int(cooldown_seg - passados)}s antes de repetir essa ação."
            except Exception:
                pass

    limite = PLANOS_COTA_MENSAL.get(tipo_acao, {}).get(plano, 0)
    if limite is not None:
        if _contar_execucoes_mes(user_id, tipo_acao) >= limite:
            return False, f"Limite mensal do plano {plano.upper()} atingido ({limite}x). Fale com o suporte pra aumentar sua cota."

    return True, ""

def registrar_execucao_acao(user_id: str, tipo_acao: str, titulo: str = None):
    """Grava a execução na tabela atividades (histórico/cooldown) E
    incrementa o contador rápido em uso_organizacao (cota mensal)."""
    if not user_id:
        return
    try:
        supabase.table("atividades").insert({
            "user_id": user_id,
            "tipo": tipo_acao,
            "titulo": titulo or tipo_acao,
            "status": "concluido",
            "detalhes": {},
        }).execute()
    except Exception:
        pass
    try:
        supabase.rpc("incrementar_uso_organizacao", {
            "p_user_id": user_id,
            "p_tipo_acao": tipo_acao,
            "p_delta": 1,
        }).execute()
    except Exception:
        pass  # se a função ainda não existir (migração não rodada), não quebra nada

class _RespostaBloqueada:
    """Objeto-substituto com atributo .text — mesma interface da resposta
    do Gemini. Assim, se uma ação for bloqueada por cooldown/cota, o
    código existente que faz `resposta.text` continua funcionando sem
    quebrar, só mostrando o motivo do bloqueio no lugar da resposta."""
    def __init__(self, texto):
        self.text = texto

def gerar_com_ia(prompt_ou_parts, tipo_acao: str = "analise_ia", user_id: str = None):
    """Substituto direto de `gemini_model.generate_content(...)` que
    aplica cooldown + cota mensal antes de gastar uma chamada de IA.

    Passe `user_id` explicitamente quando chamar de uma thread em
    background — `st.session_state` não é seguro de acessar fora da
    thread principal do Streamlit, então sem isso o cooldown/cota seria
    pulado silenciosamente em vez de aplicado."""
    if user_id is None:
        user_id = st.session_state.user.id if st.session_state.get("user") else None
    if user_id:
        permitido, motivo = verificar_pode_executar_acao(user_id, tipo_acao)
        if not permitido:
            st.toast(f"{motivo}", icon="⏳")
            return _RespostaBloqueada(f"⏳ {motivo}")
        registrar_execucao_acao(user_id, tipo_acao, "Análise de IA")
    return gemini_model.generate_content(prompt_ou_parts)


