# ── Força fundo branco via JavaScript — bypass garantido do st-emotion-cache ──
components.html("""
<script>
(function() {
    var TAGS_IGNORADAS = ['iframe','canvas','img','svg','video','input','textarea','select','option','button'];

    function forcarBranco() {
        var containers = window.parent.document.querySelectorAll(
            '[data-testid="stVerticalBlockBorderWrapper"], ' +
            '[data-testid="stVerticalBlockBorderWrapper"] *'
        );
        containers.forEach(function(el) {
            var tag = el.tagName.toLowerCase();
            if (TAGS_IGNORADAS.indexOf(tag) === -1) {
                if (el.closest('button')) {
                    // Miolo (texto/ícone) de botões: nunca pintar de branco —
                    // limpa qualquer resquício de execuções anteriores deste script.
                    el.style.removeProperty('background');
                    el.style.removeProperty('background-color');
                } else if (el.closest('[data-baseweb="select"], [data-testid="stSelectbox"]')) {
                    // Caixa visível do select (div interna) segue o mesmo
                    // cinza claro definido no CSS para inputs/selects.
                    el.style.setProperty('background', '#f3f4f6', 'important');
                    el.style.setProperty('background-color', '#f3f4f6', 'important');
                } else {
                    el.style.setProperty('background', '#ffffff', 'important');
                    el.style.setProperty('background-color', '#ffffff', 'important');
                }
            }
        });

        // Botões "Salvar" (identificados pela key estável .st-key-btn_salvar_*)
        // recebem a cor azul explicitamente aqui, com a mesma prioridade máxima
        // usada acima — assim nenhuma outra regra consegue apagar a cor deles.
        var botoesPrimary = window.parent.document.querySelectorAll(
            '.st-key-btn_salvar_empresa button, ' +
            '.st-key-btn_salvar_concorrente button'
        );
        botoesPrimary.forEach(function(btn) {
            btn.style.setProperty('background', '#0780c0', 'important');
            btn.style.setProperty('background-color', '#0780c0', 'important');
            btn.style.setProperty('color', '#ffffff', 'important');
            btn.style.setProperty('border', 'none', 'important');
            btn.querySelectorAll('*').forEach(function(inner) {
                inner.style.setProperty('color', '#ffffff', 'important');
                inner.style.setProperty('background', 'transparent', 'important');
                inner.style.setProperty('background-color', 'transparent', 'important');
            });
        });

        // Demais botões dentro dos cards (ex: "Cancelar") só têm o inline antigo
        // limpo, deixando o CSS normal do app definir a aparência.
        var botoesResto = window.parent.document.querySelectorAll(
            '[data-testid="stVerticalBlockBorderWrapper"] button'
        );
        botoesResto.forEach(function(btn) {
            if (!btn.closest('.st-key-btn_salvar_empresa') && !btn.closest('.st-key-btn_salvar_concorrente')) {
                btn.style.removeProperty('background');
                btn.style.removeProperty('background-color');
            }
        });
    }

    forcarBranco();
    setTimeout(forcarBranco, 200);
    setTimeout(forcarBranco, 500);
    setTimeout(forcarBranco, 1000);
    setTimeout(forcarBranco, 2000);

    var observer = new MutationObserver(function() {
        forcarBranco();
    });

    observer.observe(window.parent.document.body, {
        childList: true,
        subtree: true,
        attributes: false
    });
})();
</script>
""", height=0)

# ── Força a fonte (Source Sans) via JavaScript — garante que os campos
#    de texto e os selects fiquem com a MESMA font-family real usada
#    pelo Streamlit internamente, via inline style important (que vence
#    qualquer CSS, mesmo com !important). ──
components.html("""
<script>
(function() {
    function forcarFonte() {
        var doc = window.parent.document;

        // Campos de texto normais (inputs e textareas dentro do app)
        var campos = doc.querySelectorAll(
            'section.main input, section.main textarea, ' +
            'input[role="combobox"]'
        );
        campos.forEach(function(el) {
            el.style.setProperty('font-family', '"Source Sans", sans-serif', 'important');
            el.style.setProperty('font-size', '0.875rem', 'important');
        });

        // Lista de opções do select, que o Streamlit renderiza em portal
        // fora da árvore de section.main (por isso precisa buscar no doc todo)
        var opcoes = doc.querySelectorAll(
            '[data-baseweb="popover"] li, [data-baseweb="popover"] [role="option"], ' +
            '[data-baseweb="menu"] li, [data-baseweb="menu"] [role="option"], ' +
            'ul[role="listbox"] li, ul[role="listbox"] [role="option"], [role="option"]'
        );
        opcoes.forEach(function(el) {
            el.style.setProperty('font-family', '"Source Sans", sans-serif', 'important');
            el.style.setProperty('font-size', '0.875rem', 'important');
            el.querySelectorAll('*').forEach(function(inner) {
                inner.style.setProperty('font-family', '"Source Sans", sans-serif', 'important');
                inner.style.setProperty('font-size', '0.875rem', 'important');
            });
        });
    }

    forcarFonte();
    setTimeout(forcarFonte, 200);
    setTimeout(forcarFonte, 500);
    setTimeout(forcarFonte, 1000);
    setTimeout(forcarFonte, 2000);

    var observerFonte = new MutationObserver(function() {
        forcarFonte();
    });

    observerFonte.observe(window.parent.document.body, {
        childList: true,
        subtree: true,
        attributes: false
    });
})();
</script>
""", height=0)

