def _suporte_resumo_cc_youtube_v153(user_id: str) -> dict:
    """
    Conta vídeos únicos do YouTube presentes no Google Ads diretamente no
    gads_cache. Não usa `midias`, porque links YouTube são externos e o CC
    fica salvo no próprio anúncio (`video_cc_raw`).
    """
    _cache = _carregar_gads_cache_cc_v153(user_id)
    _videos = {}
    _por_empresa = {}

    for _empresa, _entry in (_cache or {}).items():
        _empresa_map = {}
        for _ad in (_entry or {}).get("data", []) or []:
            _cc = str(_ad.get("video_cc_raw") or "").strip()
            for _url in (_ad.get("videos") or []):
                _vid = _youtube_video_id_v150(_url)
                if not _vid:
                    continue
                # Se qualquer ocorrência do mesmo vídeo tiver CC, considera CC.
                _prev = _videos.get(_vid, False)
                _videos[_vid] = bool(_prev or _cc)
                _prev_emp = _empresa_map.get(_vid, False)
                _empresa_map[_vid] = bool(_prev_emp or _cc)
        if _empresa_map:
            _por_empresa[_empresa] = {
                "total": len(_empresa_map),
                "com_cc": sum(1 for _ok in _empresa_map.values() if _ok),
                "sem_cc": sum(1 for _ok in _empresa_map.values() if not _ok),
            }

    _total = len(_videos)
    _com = sum(1 for _ok in _videos.values() if _ok)
    return {
        "total": _total,
        "com_cc": _com,
        "sem_cc": _total - _com,
        "por_empresa": _por_empresa,
    }


def _suporte_inventario_midias(user_id: str) -> list:
    """Monta uma visão administrativa única das mídias salvas e pendentes.

    A fonte principal é o cache dos anúncios (`ads_cache` + `gads_cache`),
    porque é nele que conseguimos enxergar também as mídias que AINDA estão
    apenas como link externo e nunca chegaram a gerar uma linha em `midias`.
    A tabela `midias` entra como complemento para indicar transcrição/OCR e
    também para incluir arquivos permanentes órfãos do cache atual.
    """
    if not user_id:
        return []
    try:
        _ci = (
            supabase.table("ci_dados")
            .select("ads_cache,gads_cache")
            .eq("user_id", user_id)
            .execute()
        )
        _row = _ci.data[0] if _ci.data else {}
        _ads_cache = _row.get("ads_cache") or {}
        _gads_cache = _row.get("gads_cache") or {}
    except Exception:
        _ads_cache, _gads_cache = {}, {}

    try:
        _mid_res = (
            supabase.table("midias")
            .select("id,empresa,ad_id,tipo,url_origem,url_cdn,storage_key,mime_type,transcricao,ocr_texto,ocr_estruturado,criado_em")
            .eq("user_id", user_id)
            .limit(10000)
            .execute()
        )
        _mid_rows = _mid_res.data or []
    except Exception:
        _mid_rows = []

    _por_cdn = {}
    _por_origem = {}
    for _m in _mid_rows:
        if _m.get("url_cdn"):
            _por_cdn[_m["url_cdn"]] = _m
        if _m.get("url_origem"):
            _por_origem[_m["url_origem"]] = _m

    _itens = []
    _vistos = set()

    # Mapa do formato real de cada anúncio do Google Ads. Um anúncio em
    # formato Vídeo pode carregar também uma imagem de capa/thumbnail em
    # `images`; essa imagem NÃO é uma peça gráfica pendente de OCR.
    _gads_formato_por_ad = {}
    for _empresa_fmt, _entry_fmt in (_gads_cache or {}).items():
        for _ad_fmt in (_entry_fmt.get("data") or []):
            _aid_fmt = str(_ad_fmt.get("id") or "")
            _fmt = (_ad_fmt.get("formato") or "").strip()
            if _fmt == "Imagem":
                _fmt = "Gráfico"
            if _aid_fmt:
                _gads_formato_por_ad[(_empresa_fmt or "Sem empresa", _aid_fmt)] = _fmt

    def _add_cache(_cache, _plataforma):
        for _empresa, _entry in (_cache or {}).items():
            for _ad in (_entry.get("data") or []):
                _ad_id = str(_ad.get("id") or "")
                for _tipo, _campo in (("imagem", "images"), ("video", "videos")):
                    for _idx, _url in enumerate(_ad.get(_campo) or []):
                        if not _url:
                            continue
                        _chave = (_plataforma, _empresa, _ad_id, _tipo, _url)
                        if _chave in _vistos:
                            continue
                        _vistos.add(_chave)
                        _salva = bool(R2_PUBLIC_BASE and _url.startswith(R2_PUBLIC_BASE))
                        _m = _por_cdn.get(_url) or _por_origem.get(_url) or {}
                        _trans = _m.get("transcricao")
                        _ocr = _m.get("ocr_texto")
                        _empresa_norm = _empresa or "Sem empresa"
                        _formato_ad = ""
                        if _plataforma == "Google Ads":
                            _formato_ad = _gads_formato_por_ad.get((_empresa_norm, _ad_id), "")
                        # Imagem associada a anúncio de formato Vídeo é capa/thumbnail:
                        # continua sendo inventariada como mídia, mas não entra como
                        # "imagem sem OCR" e não oferece ação de refazer OCR.
                        _ocr_elegivel = (
                            _tipo == "imagem"
                            and _plataforma == "Google Ads"
                            and _formato_ad != "Vídeo"
                        )
                        if _tipo == "video":
                            _motivo_ocr = "Vídeo — processamento por transcrição; OCR não se aplica"
                        elif _plataforma != "Google Ads":
                            _motivo_ocr = "Imagem fora do Google Ads — OCR não se aplica"
                        elif _formato_ad == "Vídeo":
                            _motivo_ocr = "Capa/thumbnail de anúncio em vídeo — OCR não se aplica"
                        elif bool((_ocr or "").strip()):
                            _motivo_ocr = "OCR concluído"
                        else:
                            _motivo_ocr = "OCR pendente ou não executado"
                        _eh_youtube = bool(_tipo == "video" and _e_url_youtube(_url))
                        _itens.append({
                            "empresa": _empresa_norm,
                            "plataforma": _plataforma,
                            "ad_id": _ad_id,
                            "formato_anuncio": _formato_ad,
                            "tipo": _tipo,
                            "indice": _idx,
                            "url": _url,
                            "eh_youtube": _eh_youtube,
                            # virar arquivo permanente. YouTube é uma categoria própria.
                            "so_link_pendente": bool((not _salva) and (not _eh_youtube)),
                            "salva": _salva,
                            "midia_id": _m.get("id"),
                            "url_origem": _m.get("url_origem") or (None if _salva else _url),
                            "url_cdn": _m.get("url_cdn") or (_url if _salva else None),
                            "transcricao": _trans,
                            "tem_transcricao": bool((_trans or "").strip()),
                            "ocr_texto": _ocr,
                            "tem_ocr": bool((_ocr or "").strip()),
                            "ocr_elegivel": _ocr_elegivel,
                            "motivo_ocr": _motivo_ocr,
                            "origem_cache": True,
                        })

    _add_cache(_ads_cache, "Meta Ads")
    _add_cache(_gads_cache, "Google Ads")

    # Inclui arquivos permanentes que ainda existem no banco, mas não aparecem
    # mais no cache atual (útil pra suporte detectar sobra/orfandade de dados).
    _urls_vistas = {i["url"] for i in _itens}
    for _m in _mid_rows:
        _url = _m.get("url_cdn")
        if not _url or _url in _urls_vistas:
            continue
        _orig = _m.get("url_origem") or ""
        _plat = _plataforma_da_url(_orig)
        _tipo = _m.get("tipo") or ("video" if ("video" in (_m.get("mime_type") or "")) else "imagem")
        _trans = _m.get("transcricao")
        _ocr = _m.get("ocr_texto")
        _empresa_norm = _m.get("empresa") or "Sem empresa"
        _ad_id_norm = str(_m.get("ad_id") or "")
        _formato_ad = _gads_formato_por_ad.get((_empresa_norm, _ad_id_norm), "") if _plat == "Google Ads" else ""
        _ocr_elegivel = (
            _tipo == "imagem"
            and _plat == "Google Ads"
            and _formato_ad != "Vídeo"
        )
        if _tipo == "video":
            _motivo_ocr = "Vídeo — processamento por transcrição; OCR não se aplica"
        elif _plat != "Google Ads":
            _motivo_ocr = "Imagem fora do Google Ads — OCR não se aplica"
        elif _formato_ad == "Vídeo":
            _motivo_ocr = "Capa/thumbnail de anúncio em vídeo — OCR não se aplica"
        elif bool((_ocr or "").strip()):
            _motivo_ocr = "OCR concluído"
        else:
            _motivo_ocr = "OCR pendente ou não executado"
        _eh_youtube = bool(_tipo == "video" and _e_url_youtube(_orig or _url))
        _itens.append({
            "empresa": _empresa_norm,
            "plataforma": _plat,
            "ad_id": _ad_id_norm,
            "formato_anuncio": _formato_ad,
            "tipo": _tipo,
            "indice": 0,
            "url": _url,
            "eh_youtube": _eh_youtube,
            "so_link_pendente": False,
            "salva": True,
            "midia_id": _m.get("id"),
            "url_origem": _orig or None,
            "url_cdn": _url,
            "transcricao": _trans,
            "tem_transcricao": bool((_trans or "").strip()),
            "ocr_texto": _ocr,
            "tem_ocr": bool((_ocr or "").strip()),
            "ocr_elegivel": _ocr_elegivel,
            "motivo_ocr": _motivo_ocr,
            "origem_cache": False,
        })
    return _itens


def _suporte_resumo_midias_por_empresa(itens: list) -> list:
    """Resumo de suporte separando mídia pendente de link YouTube.

    V163:
    - `Só link` = mídia externa ainda não persistida (exclui YouTube);
    - `YouTube` = links de vídeo hospedados no YouTube, que permanecem externos
      por desenho e só desaparecem se o anúncio/link for removido;
    - transcrição normal contabiliza apenas vídeos não-YouTube; YouTube usa CC.
    """
    _grupos = {}
    for _i in itens or []:
        _g = _grupos.setdefault(_i["empresa"], {
            "Empresa": _i["empresa"],
            "Mídias": 0,
            "Salvas": 0,
            "Só link": 0,
            "YouTube": 0,
            "Vídeos": 0,
            "Com transcrição": 0,
            "Sem transcrição": 0,
            "Imagens c/ OCR": 0,
            "Imagens s/ OCR": 0,
        })
        _g["Mídias"] += 1
        _eh_youtube = bool(_i.get("eh_youtube"))
        if _eh_youtube:
            _g["YouTube"] += 1
        elif _i.get("salva"):
            _g["Salvas"] += 1
        elif _i.get("so_link_pendente", not _i.get("salva")):
            _g["Só link"] += 1

        if _i.get("tipo") == "video" and not _eh_youtube:
            _g["Vídeos"] += 1
            _g["Com transcrição" if _i.get("tem_transcricao") else "Sem transcrição"] += 1
        if _i.get("ocr_elegivel"):
            _g["Imagens c/ OCR" if _i.get("tem_ocr") else "Imagens s/ OCR"] += 1
    return sorted(_grupos.values(), key=lambda x: x["Empresa"].lower())


def _suporte_refazer_midia_especifica(user_id: str, item: dict):
    """Refaz apenas a etapa necessária da mídia escolhida no painel."""
    if not item:
        return False, "Mídia não encontrada."
    _empresa = item.get("empresa") or ""
    _tipo = item.get("tipo") or ""
    _plataforma = item.get("plataforma") or "Meta Ads"

    # Link externo: baixa somente ESTA URL, salva no R2 e troca a URL no
    # cache inteiro via RPC atômica (sem reprocessar o anúncio completo).
    if not item.get("salva"):
        _url_antiga = item.get("url") or item.get("url_origem") or ""
        if not _url_antiga:
            return False, "Link original vazio."
        _url_nova = baixar_e_persistir_midia(
            _url_antiga, user_id, _empresa, _tipo,
            item.get("ad_id") or None,
        )
        if not _url_nova or _url_nova == _url_antiga:
            return False, "A mídia continuou apenas como link. Veja as notificações/logs para o motivo."
        try:
            supabase.rpc(_rpc_substituir_url_cache(_plataforma), {
                "p_user_id": user_id,
                "p_url_antiga": _url_antiga,
                "p_url_nova": _url_nova,
            }).execute()
        except Exception as _e:
            return False, f"Arquivo salvo, mas não consegui atualizar o cache: {_e}"
        if _tipo == "video":
            iniciar_transcricao_pendente_background(user_id, _empresa)
        elif _tipo == "imagem" and _plataforma == "Google Ads":
            iniciar_ocr_pendente_background(user_id, _empresa)
        return True, "Mídia salva novamente e enviada para o processamento correspondente."

    # Arquivo já permanente: refaz só o processamento derivado.
    try:
        if _tipo == "video":
            _q = supabase.table("midias").update({"transcricao": None}).eq("user_id", user_id)
            if item.get("midia_id"):
                _q = _q.eq("id", item["midia_id"])
            else:
                _q = _q.eq("url_cdn", item.get("url_cdn") or item.get("url"))
            _q.execute()
            iniciar_transcricao_pendente_background(user_id, _empresa)
            return True, "Transcrição desta mídia enviada para refazer."

        if _tipo == "imagem" and _plataforma == "Google Ads":
            _q = supabase.table("midias").update({
                "ocr_texto": None,
                "ocr_estruturado": None,
            }).eq("user_id", user_id)
            if item.get("midia_id"):
                _q = _q.eq("id", item["midia_id"])
            else:
                _q = _q.eq("url_cdn", item.get("url_cdn") or item.get("url"))
            _q.execute()
            iniciar_ocr_pendente_background(user_id, _empresa)
            return True, "OCR desta imagem enviado para refazer."

        return False, "Essa mídia não tem uma etapa individual de OCR/transcrição para refazer."
    except Exception as _e:
        return False, f"Não foi possível refazer esta mídia: {_e}"

